from uuid import UUID, uuid4

from fastapi import Request
from starlette.middleware.base import BaseHTTPMiddleware
from structlog.contextvars import bind_contextvars, clear_contextvars


class CorrelationMiddleware(BaseHTTPMiddleware):
    header_name: str = "X-Correlation-ID"

    async def dispatch(self, request: Request, call_next):
        raw_id = request.headers.get(self.header_name)
        if raw_id:
            try:
                correlation_id = UUID(raw_id)
            except ValueError:
                correlation_id = uuid4()
        else:
            correlation_id = uuid4()

        clear_contextvars()
        bind_contextvars(correlation_id=str(correlation_id))
        request.state.correlation_id = correlation_id

        try:
            response = await call_next(request)
            response.headers[self.header_name] = str(correlation_id)
            return response
        finally:
            clear_contextvars()from __future__ import annotations

import structlog
from fastapi import Request
from fastapi.responses import JSONResponse

from skriptoteket.domain.errors import DomainError, ErrorCode
from skriptoteket.web.error_mapping import error_to_status

logger = structlog.get_logger(__name__)


async def error_handler_middleware(request: Request, call_next):
    try:
        return await call_next(request)
    except DomainError as exc:
        correlation_id = getattr(request.state, "correlation_id", None)
        status_code = error_to_status(exc.code)

        logger.warning(
            "Application error",
            error_code=exc.code.value,
            http_status=status_code,
            method=request.method,
            path=request.url.path,
            correlation_id=str(correlation_id) if correlation_id else None,
        )

        return JSONResponse(
            status_code=status_code,
            content={
                "error": {
                    "code": exc.code.value,
                    "message": exc.message,
                    "details": exc.details,
                },
                "correlation_id": str(correlation_id) if correlation_id else None,
            },
        )
    except Exception:
        correlation_id = getattr(request.state, "correlation_id", None)
        logger.exception(
            "Unhandled exception",
            method=request.method,
            path=request.url.path,
            correlation_id=str(correlation_id) if correlation_id else None,
        )
        return JSONResponse(
            status_code=500,
            content={
                "error": {
                    "code": ErrorCode.INTERNAL_ERROR.value,
                    "message": "Internal server error",
                    "details": {},
                },
                "correlation_id": str(correlation_id) if correlation_id else None,
            },
        )from __future__ import annotations

from uuid import UUID

from fastapi import Request


def get_client_ip(request: Request) -> str | None:
    forwarded_for = request.headers.get("x-forwarded-for")
    if forwarded_for:
        return forwarded_for.split(",")[0].strip() or None

    real_ip = request.headers.get("x-real-ip")
    if real_ip:
        return real_ip.strip() or None

    if request.client:
        return request.client.host
    return None


def get_user_agent(request: Request) -> str | None:
    user_agent = request.headers.get("user-agent")
    return user_agent.strip() if user_agent else None


def get_correlation_id(request: Request) -> UUID | None:
    correlation_id = getattr(request.state, "correlation_id", None)
    return correlation_id if isinstance(correlation_id, UUID) else None---
type: story
id: ST-08-28
title: "AI: platform-only full model response capture on edit-ops/preview failures (Option A)"
status: done
owners: "agents"
created: 2026-01-11
updated: 2026-01-11
epic: "EPIC-08"
acceptance_criteria:
  - "Given `LLM_CAPTURE_ON_ERROR_ENABLED=true`, when `POST /api/v1/editor/edit-ops` fails (timeout/over-budget/truncated/parse_failed/invalid_ops/error), then the backend writes a capture under `ARTIFACTS_ROOT/llm-captures/` keyed by the request correlation id."
  - "Given `LLM_CAPTURE_ON_ERROR_ENABLED=true`, when `POST /api/v1/editor/edit-ops/preview` returns ok=false, then the backend writes a capture under `ARTIFACTS_ROOT/llm-captures/` keyed by the request correlation id."
  - "Given captures are enabled, then no raw prompt/code/model output content is emitted to normal structured logs; logs remain metadata-only."
  - "Given capture writing fails (missing dir, permissions, disk full), then the request still succeeds/fails normally and the backend logs a metadata-only `llm_capture_write_failed` event."
  - "Given captures exist, then a platform developer can retrieve them via filesystem/SSH; no HTTP endpoint exposes capture contents."
  - "Given capture directories are older than retention, when the artifacts prune job runs, then capture directories are removed."
ui_impact: "No"
data_impact: "Yes (stores sensitive debug captures on disk when enabled)"
---

## Context

We need a production-configurable (OFF by default) “god mode” debug mechanism to diagnose model behavior when edit-ops
generation or preview fails, without leaking prompt/code/output content into normal observability logs or tool developer
surfaces.

## Notes

- Option A: captures are stored in artifact storage and retrieved via server filesystem access (SSH).
- Capture id is the request correlation id (stable, already propagated).

## Implementation (done)

- Config: `LLM_CAPTURE_ON_ERROR_ENABLED` (default OFF).
- Capture location: `${ARTIFACTS_ROOT}/llm-captures/<kind>/<correlation_id>/capture.json`.
- Pruning: `pdm run python -m skriptoteket.cli prune-artifacts` (includes `llm-captures/`).export function createCorrelationId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }

  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (char) => {
    const random = Math.random() * 16;
    const value = char === "x" ? random : (random % 4) + 8;
    return Math.floor(value).toString(16);
  });
}import type { EditorEditOpsOpOutput } from "./editOpsState";
import type { VirtualFileId, VirtualFileTextMap } from "../virtualFiles";
import type { EditOpsDiffItem } from "./editOpsState";

export function uniqueTargetFiles(ops: EditorEditOpsOpOutput[]): VirtualFileId[] {
  const seen = new Set<VirtualFileId>();
  const ordered: VirtualFileId[] = [];
  for (const op of ops) {
    if (!seen.has(op.target_file)) {
      seen.add(op.target_file);
      ordered.push(op.target_file);
    }
  }
  return ordered;
}

export function buildDiffItems(params: {
  targetFiles: VirtualFileId[];
  beforeFiles: VirtualFileTextMap;
  afterFiles: VirtualFileTextMap;
}): EditOpsDiffItem[] {
  const { targetFiles, beforeFiles, afterFiles } = params;
  return targetFiles
    .filter((fileId) => beforeFiles[fileId] !== afterFiles[fileId])
    .map((fileId) => ({
      virtualFileId: fileId,
      beforeText: beforeFiles[fileId],
      afterText: afterFiles[fileId],
    }));
}import type { EditorView } from "@codemirror/view";
import type { EditorEditOpsCursor, EditorEditOpsSelection } from "./editorEditOpsApi";

type ResolveSelectionParams = {
  view: EditorView | null;
  includeCursorWhenNoSelection: boolean;
};

type ResolveSelectionResult = {
  selection: EditorEditOpsSelection | null;
  cursor: EditorEditOpsCursor | null;
};

export function resolveEditOpsSelection({
  view,
  includeCursorWhenNoSelection,
}: ResolveSelectionParams): ResolveSelectionResult {
  if (!view) {
    return { selection: null, cursor: null };
  }

  const main = view.state.selection.main;
  if (!main.empty) {
    return {
      selection: { from: main.from, to: main.to },
      cursor: { pos: main.to },
    };
  }

  return {
    selection: null,
    cursor: includeCursorWhenNoSelection ? { pos: main.from } : null,
  };
}import type { Ref } from "vue";

import type { VirtualFileTextMap } from "../virtualFiles";

type EditorFieldRefs = {
  entrypoint: Ref<string>;
  sourceCode: Ref<string>;
  settingsSchemaText: Ref<string>;
  inputSchemaText: Ref<string>;
  usageInstructions: Ref<string>;
};

type AppliedEditOpsSnapshot = {
  beforeFiles: VirtualFileTextMap;
  afterFiles: VirtualFileTextMap;
  beforeFingerprint: string;
  afterFingerprint: string;
  appliedAt: string;
};

export function cloneVirtualFiles(files: VirtualFileTextMap): VirtualFileTextMap {
  return { ...files };
}

export function virtualFilesFingerprint(files: VirtualFileTextMap): string {
  return [
    files["entrypoint.txt"],
    files["tool.py"],
    files["settings_schema.json"],
    files["input_schema.json"],
    files["usage_instructions.md"],
  ].join("\u0000");
}

export function applyVirtualFiles(fields: EditorFieldRefs, nextFiles: VirtualFileTextMap): void {
  fields.entrypoint.value = nextFiles["entrypoint.txt"];
  fields.sourceCode.value = nextFiles["tool.py"];
  fields.settingsSchemaText.value = nextFiles["settings_schema.json"];
  fields.inputSchemaText.value = nextFiles["input_schema.json"];
  fields.usageInstructions.value = nextFiles["usage_instructions.md"];
}

export function createAppliedSnapshot(
  beforeFiles: VirtualFileTextMap,
  afterFiles: VirtualFileTextMap,
): AppliedEditOpsSnapshot {
  return {
    beforeFiles,
    afterFiles,
    beforeFingerprint: virtualFilesFingerprint(beforeFiles),
    afterFingerprint: virtualFilesFingerprint(afterFiles),
    appliedAt: new Date().toISOString(),
  };
}

