class UnifiedDiffHunk(BaseModel):
    model_config = ConfigDict(frozen=True)

    index: int
    header: str
    old_start: int
    old_count: int
    new_start: int
    new_count: int


class PreparedUnifiedDiff(BaseModel):
    model_config = ConfigDict(frozen=True)

    target_file: VirtualFileId
    normalized_diff: str
    patch_id: str
    normalizations_applied: list[str] = Field(default_factory=list)
