DEFAULT_ENTRYPOINT = "run_tool"
STARTER_TEMPLATE = '''"""
SKRIPTOTEKET STARTMALL
======================
Detta är en mall som visar hur verktyg i Skriptoteket fungerar.
ERSÄTT denna kod med din egen verktygslogik.

Demonstrerar:
- Indatafiler via SKRIPTOTEKET_INPUT_MANIFEST
- Indata via SKRIPTOTEKET_INPUTS (första körningen)
  och SKRIPTOTEKET_ACTION (uppföljning via next_actions)
- Användarinställningar via SKRIPTOTEKET_MEMORY_PATH
- Utdatatyper: notice, markdown, table (+ fler i kommentarer)
- Skriva artefakter till output_dir
- next_actions och state
"""
from __future__ import annotations

import csv
import json
import os
from pathlib import Path

from pdf_helper import save_as_pdf


def _read_json_env(name: str) -> object | None:
    raw = os.environ.get(name, "").strip()
    if not raw:
        return None
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return None


def run_tool(input_dir: str, output_dir: str) -> dict:
    output_root = Path(output_dir)
    output_root.mkdir(parents=True, exist_ok=True)

    # ─── INDATA (första körningen eller uppföljning) ───
    # Första körningen: SKRIPTOTEKET_INPUTS (JSON-objekt, inga filer).
    # Uppföljning (next_actions): SKRIPTOTEKET_ACTION (JSON med {action_id, input, state}).
    action = _read_json_env("SKRIPTOTEKET_ACTION")

    action_id: str | None = None
    inputs: dict = {}
    state_in: dict | None = None

    if isinstance(action, dict) and action:
        action_id_raw = action.get("action_id")
        action_id = str(action_id_raw).strip() if action_id_raw else None

        action_input = action.get("input")
        inputs = action_input if isinstance(action_input, dict) else {}

        action_state = action.get("state")
        state_in = action_state if isinstance(action_state, dict) else None
    else:
        inputs_raw = _read_json_env("SKRIPTOTEKET_INPUTS")
        inputs = inputs_raw if isinstance(inputs_raw, dict) else {}
    # Exempel: title = inputs.get("title")

    # ─── INDATAFILER ───
    # Manifest innehåller: name (originalnamn), path (absolut sökväg), bytes (storlek)
    manifest = _read_json_env("SKRIPTOTEKET_INPUT_MANIFEST")
    files = []
    if isinstance(manifest, dict) and isinstance(manifest.get("files"), list):
        files = manifest["files"]

    # ─── ANVÄNDARINSTÄLLNINGAR (valfritt) ───
    # Läs inställningar som användaren sparat via "Inställningar"-panelen
    settings: dict = {}
    memory_path = os.environ.get("SKRIPTOTEKET_MEMORY_PATH")
    if memory_path and Path(memory_path).exists():
        memory = json.loads(Path(memory_path).read_text())
        if isinstance(memory, dict) and isinstance(memory.get("settings"), dict):
            settings = memory["settings"]
    # Exempel: threshold = settings.get("threshold", 10)

    # ─── BEARBETA FILER ───
    file_rows = []
    for f in files:
        if not isinstance(f, dict):
            continue
        file_rows.append(
            {
                "name": f.get("name"),
                "path": f.get("path"),
                "bytes": f.get("bytes"),
            }
        )

    threshold = None
    if action_id == "refine":
        try:
            threshold = int(inputs.get("threshold", 0))
        except (TypeError, ValueError):
            threshold = 0
        file_rows = [
            row
            for row in file_rows
            if isinstance(row.get("bytes"), int) and row["bytes"] >= threshold
        ]

        export_format = str(inputs.get("format", "")).strip().lower()
        if export_format == "csv":
            export_path = output_root / "uppladdade_filer.csv"
            with export_path.open("w", encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=["name", "bytes", "path"])
                writer.writeheader()
                writer.writerows(file_rows)
        elif export_format == "pdf":
            rows_html = "".join(
                f"<tr><td>{row.get('name','')}</td><td>{row.get('bytes','')}</td></tr>"
                for row in file_rows
            )
            html = f"""
            <h1>Uppladdade filer</h1>
            <p>Tröskel: {threshold} byte</p>
            <table border="1" cellspacing="0" cellpadding="6">
              <thead><tr><th>Namn</th><th>Storlek (byte)</th></tr></thead>
              <tbody>{rows_html}</tbody>
            </table>
            """
            save_as_pdf(html, output_dir, "uppladdade_filer.pdf")

    # ─── SKRIV ARTEFAKT (valfritt) ───
    # Filer i output_dir blir nedladdningsbara artefakter
    summary_path = output_root / "sammanfattning.txt"
    summary_path.write_text(
        (
            f"Åtgärd: {action_id}\\n"
            f"Antal filer: {len(files)}\\n"
            f"Indata: {inputs}\\n"
            f"Inställningar: {settings}"
        )
    )

    # ─── STATE (valfritt) ───
    # state sparas mellan körningar och skickas tillbaka vid nästa run
    # (t.ex. uppföljning via next_actions)
    state = state_in or {}
    runs = state.get("runs")
    state["runs"] = runs + 1 if isinstance(runs, int) else 1

    # ─── RETURNERA RESULTAT ───
    outputs = [
        # notice: Snabbmeddelanden (info/warning/error)
        {
            "kind": "notice",
            "level": "info",
            "message": (
                f"{len(files)} fil(er) mottagna."
                if threshold is None
                else f"{len(file_rows)} fil(er) matchade tröskel ≥ {threshold}."
            ),
        },
        # markdown: Formaterad text
        {
            "kind": "markdown",
            "markdown": (
                "## Resultat\\n\\n"
                "Ersätt denna mall med din egen logik.\\n\\n"
                f"**Körningar i denna session:** {state['runs']}\\n"
            ),
        },
        # table: Strukturerad data
        {
            "kind": "table",
            "title": "Uppladdade filer",
            "columns": [
                {"key": "name", "label": "Namn"},
                {"key": "bytes", "label": "Storlek (byte)"},
            ],
            "rows": file_rows,
        },
    ]

    # ─── AVANCERAT: FLER UTDATATYPER (avkommentera vid behov) ───
    # json: Visa rådata
    # outputs.append({"kind": "json", "title": "Debug-data", "value": {"files": files}})
    #
    # html_sandboxed: Rendera HTML i iframe (för specialfall)
    # outputs.append({"kind": "html_sandboxed", "html": "<p>Custom HTML</p>"})

    # ─── AVANCERAT: UPPFÖLJNINGSFORMULÄR (avkommentera vid behov) ───
    # next_actions låter användaren skicka in ytterligare data efter första körningen
    next_actions = [
        {
            "action_id": "refine",
            "label": "Förfina resultat",
            "kind": "form",
            "fields": [
                {"name": "threshold", "label": "Tröskel (byte)", "kind": "integer"},
                {
                    "name": "format",
                    "label": "Exportformat",
                    "kind": "enum",
                    "options": [
                        {"value": "pdf", "label": "PDF"},
                        {"value": "csv", "label": "CSV"},
                    ],
                },
            ],
        }
    ]

    return {"outputs": outputs, "next_actions": next_actions, "state": state}
'''


async def require_tool_access(
    *,
    actor: User,
    tool_id: UUID,
    maintainers: ToolMaintainerRepositoryProtocol,
) -> bool:
    if actor.role in {Role.ADMIN, Role.SUPERUSER}:
        return True

    is_tool_maintainer = await maintainers.is_maintainer(tool_id=tool_id, user_id=actor.id)
    if not is_tool_maintainer:
        raise DomainError(
            code=ErrorCode.FORBIDDEN,
            message="Insufficient permissions",
            details={"tool_id": str(tool_id)},
        )
    return is_tool_maintainer


def visible_versions_for_actor(
    *,
    actor: User,
    versions: list[ToolVersion],
    is_tool_maintainer: bool,
) -> list[ToolVersion]:
    return _visible_versions_for_actor(
        actor=actor,
        versions=versions,
        is_tool_maintainer=is_tool_maintainer,
    )


def select_default_version(
    *,
    actor: User,
    tool: Tool,
    versions: list[ToolVersion],
    is_tool_maintainer: bool,
) -> ToolVersion | None:
    visible_versions = visible_versions_for_actor(
        actor=actor,
        versions=versions,
        is_tool_maintainer=is_tool_maintainer,
    )

    if actor.role in {Role.ADMIN, Role.SUPERUSER}:
        for version in visible_versions:
            if version.state is VersionState.IN_REVIEW:
                return version

    # Prefer latest visible draft, then active, then latest visible.
    for version in visible_versions:
        if version.state is VersionState.DRAFT:
            return version

    if tool.active_version_id is not None:
        for version in visible_versions:
            if version.id == tool.active_version_id:
                return version

    return visible_versions[0] if visible_versions else None


def artifacts_for_run(run: ToolRun) -> list[dict[str, object]]:
    manifest = ArtifactsManifest.model_validate(run.artifacts_manifest)
    return [
        {
            "artifact_id": artifact.artifact_id,
            "path": artifact.path,
            "bytes": artifact.bytes,
            "download_url": f"/admin/tool-runs/{run.id}/artifacts/{artifact.artifact_id}",
        }
        for artifact in manifest.artifacts
    ]


def is_allowed_to_view_version(
    *,
    actor: User,
    version: ToolVersion,
    is_tool_maintainer: bool,
) -> bool:
    return _can_view_version(actor=actor, version=version, is_tool_maintainer=is_tool_maintainer)from __future__ import annotations

from contextlib import contextmanager
from unittest.mock import AsyncMock, MagicMock
from uuid import UUID, uuid4

import pytest
from structlog.contextvars import bind_contextvars, clear_contextvars

from skriptoteket.application.editor.edit_ops_preview_handler import EditOpsPreviewHandler
from skriptoteket.config import Settings
from skriptoteket.domain.identity.models import Role
from skriptoteket.protocols.llm import EditOpsPatchOp, EditOpsPreviewCommand
from skriptoteket.protocols.llm_captures import LlmCaptureStoreProtocol
from tests.fixtures.identity_fixtures import make_user


@contextmanager
def _bound_correlation_id(correlation_id: UUID):
    clear_contextvars()
    bind_contextvars(correlation_id=str(correlation_id))
    try:
        yield
    finally:
        clear_contextvars()


@pytest.mark.unit
@pytest.mark.asyncio
async def test_preview_writes_capture_on_coherency_error_when_enabled() -> None:
    correlation_id = uuid4()
    with _bound_correlation_id(correlation_id):
        settings = Settings(LLM_CAPTURE_ON_ERROR_ENABLED=True)
        capture_store = MagicMock(spec=LlmCaptureStoreProtocol)
        capture_store.write_capture = AsyncMock()

        handler = EditOpsPreviewHandler(
            settings=settings,
            capture_store=capture_store,
            patch_applier=MagicMock(),
        )
        actor = make_user(role=Role.CONTRIBUTOR)
        tool_id = uuid4()

        patch = (
            "diff --git a/tool.py b/tool.py\n"
            "--- a/tool.py\n"
            "+++ b/tool.py\n"
            "@@ -1 +1 @@\n"
            "-print('hi')\n"
            "+print('hej')\n"
        )
        result = await handler.handle(
            actor=actor,
            command=EditOpsPreviewCommand(
                tool_id=tool_id,
                active_file="tool.py",
                selection=None,
                cursor=None,
                virtual_files={"tool.py": "print('hi')\n"},
                ops=[
                    EditOpsPatchOp(op="patch", target_file="tool.py", patch=patch),
                    EditOpsPatchOp(op="patch", target_file="tool.py", patch=patch),
                ],
            ),
        )

        assert result.ok is False

        capture_store.write_capture.assert_awaited_once()
        kwargs = capture_store.write_capture.await_args.kwargs
        assert kwargs["kind"] == "edit_ops_preview_failure"
        assert kwargs["capture_id"] == correlation_id
        payload = kwargs["payload"]
        assert payload["outcome"] == "coherency_error"
        assert payload["error_kind"] == "coherency_error"
        assert payload["op_count"] == 2from __future__ import annotations

import pytest

from skriptoteket.infrastructure.editor.unified_diff_applier import SubprocessUnifiedDiffApplier


@pytest.mark.unit
def test_prepare_strips_code_fences_and_injects_headers() -> None:
    applier = SubprocessUnifiedDiffApplier()

    prepared = applier.prepare(
        target_file="tool.py",
        unified_diff="""
            ```diff
            @@ -1 +1 @@
            -print("hi")
            +print("hello")
            ```
        """,
    )

    assert prepared.target_file == "tool.py"
    assert prepared.normalized_diff.startswith("--- a/tool.py\n+++ b/tool.py\n@@")
    assert "stripped_code_fences" in prepared.normalizations_applied
    assert "stripped_leading_indentation" in prepared.normalizations_applied
    assert "synthesized_file_headers" in prepared.normalizations_applied


@pytest.mark.unit
def test_prepare_rejects_multi_file_diff() -> None:
    applier = SubprocessUnifiedDiffApplier()

    with pytest.raises(ValueError):
        applier.prepare(
            target_file="tool.py",
            unified_diff="""
                --- a/tool.py
                +++ b/tool.py
                @@ -1 +1 @@
                -print("hi")
                +print("hello")
                --- a/other.py
                +++ b/other.py
                @@ -1 +1 @@
                -print("x")
                +print("y")
            """,
        )


@pytest.mark.unit
def test_apply_uses_whitespace_stage() -> None:
    applier = SubprocessUnifiedDiffApplier()

    base_text = "def foo():\n\treturn 1\n"
    prepared = applier.prepare(
        target_file="tool.py",
        unified_diff="""
            --- a/tool.py
            +++ b/tool.py
            @@ -1,2 +1,2 @@
             def foo():
            -    return 1
            +    return 2
        """,
    )

    result = applier.apply(
        target_file="tool.py",
        base_text=base_text,
        prepared=prepared,
        max_fuzz=2,
        max_offset_lines=50,
        enable_whitespace_stage=True,
    )

    assert result.ok is True
    assert result.meta is not None
    assert result.meta.whitespace_ignored is True
    assert result.next_text == "def foo():\n    return 2\n"from __future__ import annotations

