type: story
id: ST-08-24
title: "AI edit ops v2: anchor/patch-based targets + apply"
status: done
owners: "agents"
created: 2026-01-10
updated: 2026-01-11
epic: "EPIC-08"
acceptance_criteria:
  - "Given the user requests an edit without explicitly targeting a location (the frontend omits both `selection` and `cursor`), when the frontend calls `POST /api/v1/editor/edit-ops`, then the backend instructs the model to return patch/anchor-based ops (no cursor-only insert ops)."
  - "Given the user has a selection in the active file, when the frontend calls `POST /api/v1/editor/edit-ops`, then it includes both `selection` and `cursor` (cursor position is explicitly defined; default to selection end) so cursor-target ops are always resolvable."
  - "Given an edit-ops response includes a `patch` op, when the frontend previews or applies it, then the backend sanitizes/normalizes the diff and applies it with a bounded fuzz ladder (0 → whitespace-tolerant strict → fuzz 1 → fuzz 2); unsafe/stale applies block apply with a regenerate message."
  - "Given an edit-ops response includes an `anchor` target, when the frontend previews or applies it, then the anchor must match exactly once in the base file or the proposal is rejected with a user-actionable error."
  - "Given a valid patch/anchor proposal across multiple virtual files, when the user clicks Apply, then all changes are applied atomically and can be undone as one change (same behavior as ST-08-22)."
  - "Given the patch/anchor payload is invalid or references non-canonical virtual files, when the backend processes the response, then it fails safely with `ops=[]` and a user-actionable assistant_message."
  - "Given an AI proposal is previewed, then the UI uses an AI-specific diff preview surface (reuse diff engine/capabilities, but not the full version-review diff UI chrome)."

dependencies:
  - "ST-08-21"
  - "ST-08-22"
  - "ST-14-17"
  - "ADR-0051"

ui_impact: "Yes (preview/apply uses patch/anchor targeting)"
data_impact: "No (protocol change only)"
---

## Context

Cursor/selection-only edit ops produce surprising inserts when the user has not
explicitly placed a cursor or selected a region. Coding assistants are expected
to locate edits by context (anchors) or patch hunks. We need a v2 edit-ops
contract that supports deterministic patch/anchor targeting without relying on
cursor position.

## Notes

- Patch ops use unified diffs with canonical virtual file ids.
- Anchor targets are strict (exact, single match) to prevent ambiguous edits.
- Reuse the existing preview/apply/undo capabilities (ST-08-22), but render diffs in an AI-specific view (minimal,
  no patch/copy/download UI intended for version review).

Related PRs:

- `docs/backlog/prs/pr-0015-editor-ai-edit-ops-anchor-patch-v2.md`
- `docs/backlog/prs/pr-0016-editor-ai-edit-ops-v2-hardening.md`---
type: runbook
id: RUN-observability-logging
title: "Runbook: Observability Logging"
status: active
owners: "olof"
created: 2025-12-16
updated: 2026-01-11
system: "skriptoteket"
---

How to debug Skriptoteket using structured logs and correlation IDs.

Reference: `docs/reference/reports/ref-external-observability-integration.md`.

## Configuration

Environment variables:

- `SERVICE_NAME` (default: `skriptoteket`)
- `ENVIRONMENT` (default: `development`)
- `LOG_LEVEL` (default: `INFO`)
- `LOG_FORMAT` (`json` or `console`)
- `LLM_CAPTURE_ON_ERROR_ENABLED` (default: `false`; platform-only, not logs)

Recommended defaults:

- Local dev: `LOG_FORMAT=console`
- Production: `LOG_FORMAT=json`

## Correlation ID

Skriptoteket accepts `X-Correlation-ID` on incoming requests and echoes it on responses. The value is bound as
`correlation_id` for logs emitted during request handling.

### Local example

```bash
CID="$(python -c 'import uuid; print(uuid.uuid4())')"
curl -i -H "X-Correlation-ID: ${CID}" http://127.0.0.1:8000/login
```

Search logs for the correlation id:

```bash
docker logs skriptoteket_web | rg "${CID}"
```

## JSON log shape (HuleEdu)

Required fields:

- `timestamp` (RFC 3339 / ISO 8601)
- `level` (`debug|info|warning|error|critical`)
- `event` (human-readable message)
- `service.name`
- `deployment.environment`

Optional fields (when available):

- `correlation_id`
- `trace_id`, `span_id` (when OpenTelemetry is enabled)

## Where to view logs

Local:

```bash
docker logs -f skriptoteket_web
```

Home server:

```bash
ssh hemma "sudo docker logs -f skriptoteket-web"
```

Grafana + Loki: see `docs/runbooks/runbook-observability-grafana.md`.

## nginx-proxy bot/probe analysis (Loki)

`nginx-proxy` access logs are shipped to Loki via Promtail. We label only low-cardinality fields:

- `vhost` (Host header / vhost)
- `client_ip` (nginx `$remote_addr`)
- `method`, `status`

Grafana dashboard (provisioned):

- `Skriptoteket nginx-proxy Security` (`observability/grafana/provisioning/dashboards/skriptoteket-nginx-proxy-security.json`)

Examples (LogQL metrics):

```logql
# Top probed vhosts (24h)
topk(10, sum by (vhost) (count_over_time({container="nginx-proxy",method=~".+"}[24h])))

# Top client IPs (24h)
topk(10, sum by (client_ip) (count_over_time({container="nginx-proxy",method=~".+"}[24h])))

# Scanner/probe patterns (24h)
sum(count_over_time({container="nginx-proxy",method=~".+"} |= "/.env" [24h]))
sum(count_over_time({container="nginx-proxy",method=~".+"} |~ "\\.git" [24h]))
sum(count_over_time({container="nginx-proxy",method=~".+"} |~ "(?i)wp-" [24h]))
sum(count_over_time({container="nginx-proxy",method=~".+"} |~ "\\.php" [24h]))
sum(count_over_time({container="nginx-proxy",method="PROPFIND"}[24h]))
```

Avoid labeling full paths (high cardinality). Use query-time filters (`|=` / `|~`) instead.

## Sensitive Data Policy

Skriptoteket handles school-related data. Observability must not become a data leakage vector.

### What MAY be logged

- User IDs, role names (e.g., `user`, `contributor`, `admin`)
- Tool IDs, tool version IDs, run IDs
- Request paths, methods, status codes
- Correlation IDs, trace IDs, span IDs
- Error types and non-sensitive error messages
- Timestamps and durations

### What MUST NOT be logged

- Passwords, tokens, secrets, API keys
- Email addresses (PII)
- Student names, personal data, school identifiers
- File contents from uploads
- Session cookies or bearer tokens
- Raw request/response bodies containing user data

### Automatic Redaction

The structlog configuration includes a redaction processor that replaces values for sensitive keys with `[REDACTED]`.
Keys matching these patterns are redacted (case-insensitive):

- `password`, `token`, `secret`
- `api_key`, `api-key`, `x-api-key`
- `authorization`, `credential`, `bearer`
- `cookie`, `session`

### Security Review Checklist

When adding new log statements, verify:

- [ ] No PII (emails, names, student data) in log events
- [ ] Sensitive data uses keys that trigger automatic redaction
- [ ] No raw request/response body logging
- [ ] Error messages don't expose internal system details
- [ ] File paths don't reveal user-specific information

## Platform-only LLM debug captures (Option A)

Skriptoteket can optionally persist **sensitive** “full model response” debug captures for edit-ops generation and
preview failures.

- This is **NOT observability logging**: normal logs remain metadata-only.
- Captures may include tool code and raw model output; treat them as sensitive platform data.
- Captures are retrievable only via filesystem/SSH (no tool-developer-facing API/UI).

### Enable

- Set `LLM_CAPTURE_ON_ERROR_ENABLED=true` (default is `false`).

### Capture id (correlation id)

- Capture id is the request `X-Correlation-ID` (also logged as `correlation_id`).
- The UI/API appends `Korrelation-ID: <uuid>` on edit-ops/preview/apply failures to make reporting easier.

### Location

Captures are written under:

```text
${ARTIFACTS_ROOT}/llm-captures/<kind>/<capture_id>/capture.json
```

Known kinds:

- `chat_ops_response` (edit-ops generation failures)
- `edit_ops_preview_failure` (preview failures)

### JSON shape

Each `capture.json` is a small envelope:

```json
{
  "version": 1,
  "kind": "<kind>",
  "capture_id": "<uuid>",
  "captured_at": "<iso8601>",
  "payload": { }
}
```

Payload contents are kind-specific and may contain sensitive data (model output, tool code, diffs/snippets).

### Access

- Local dev: inspect `${ARTIFACTS_ROOT}/llm-captures/`.
- Home server (prod): see `docs/runbooks/runbook-home-server.md` for `ssh` + `docker exec` commands.export const VIRTUAL_FILE_IDS = [
  "tool.py",
  "entrypoint.txt",
  "settings_schema.json",
  "input_schema.json",
  "usage_instructions.md",
] as const;

export type VirtualFileId = (typeof VIRTUAL_FILE_IDS)[number];

export const VIRTUAL_DIFF_FILE_IDS = [
  "tool.py",
  "settings_schema.json",
  "input_schema.json",
  "usage_instructions.md",
] as const satisfies readonly VirtualFileId[];

export type VirtualFileLanguage = "python" | "json" | "text";

export type VirtualFileMeta = {
  id: VirtualFileId;
  label: string;
  language: VirtualFileLanguage;
};

export const VIRTUAL_FILES: readonly VirtualFileMeta[] = [
  { id: "tool.py", label: "Källkod", language: "python" },
  { id: "entrypoint.txt", label: "Entrypoint", language: "text" },
  { id: "settings_schema.json", label: "Inställningar (schema)", language: "json" },
  { id: "input_schema.json", label: "Indata (schema)", language: "json" },
  { id: "usage_instructions.md", label: "Instruktioner", language: "text" },
] as const;

export function isVirtualFileId(value: unknown): value is VirtualFileId {
  return typeof value === "string" && (VIRTUAL_FILE_IDS as readonly string[]).includes(value);
}

export type VirtualFileTextMap = Record<VirtualFileId, string>;

export type EditorVirtualFileTextFields = {
  entrypoint: string;
  sourceCode: string;
  settingsSchemaText: string;
  inputSchemaText: string;
  usageInstructions: string;
};

export function virtualFileTextFromEditorFields(
  fields: EditorVirtualFileTextFields,
): VirtualFileTextMap {
  return {
    "tool.py": fields.sourceCode,
    "entrypoint.txt": fields.entrypoint,
    "settings_schema.json": fields.settingsSchemaText,
    "input_schema.json": fields.inputSchemaText,
    "usage_instructions.md": fields.usageInstructions,
  };
}

type JsonSchema = unknown[] | null | undefined;

export type EditorBootVirtualFileFields = {
  entrypoint: string;
  source_code: string;
  settings_schema?: JsonSchema;
  input_schema?: JsonSchema;
  usage_instructions?: string | null;
};

function stringifySchema(schema: JsonSchema, emptyValue: string): string {
  if (schema === null || schema === undefined) return emptyValue;
  return JSON.stringify(schema, null, 2);
}

export function virtualFileTextFromEditorBoot(fields: EditorBootVirtualFileFields): VirtualFileTextMap {
  return {
    "tool.py": fields.source_code,
    "entrypoint.txt": fields.entrypoint,
    "settings_schema.json": stringifySchema(fields.settings_schema, ""),
    "input_schema.json": stringifySchema(fields.input_schema, ""),
    "usage_instructions.md": fields.usage_instructions ?? "",
  };
}

export function virtualFileLabel(id: VirtualFileId): string {
  return VIRTUAL_FILES.find((file) => file.id === id)?.label ?? id;
}

export function virtualFileLanguage(id: VirtualFileId): VirtualFileLanguage {
  return VIRTUAL_FILES.find((file) => file.id === id)?.language ?? "text";
}from __future__ import annotations

