        error_details=[
            EditorEditOpsPreviewErrorDetails.model_validate(item.model_dump())
            for item in result.error_details
        ],
        meta=EditorEditOpsPreviewMeta.model_validate(result.meta.model_dump()),
    )from __future__ import annotations

