@pytest.mark.unit
@pytest.mark.asyncio
async def test_edit_ops_writes_capture_on_parse_failed_when_enabled() -> None:
    correlation_id = uuid4()
    with _bound_correlation_id(correlation_id):
        settings = Settings(LLM_CHAT_OPS_ENABLED=True, LLM_CAPTURE_ON_ERROR_ENABLED=True)
        provider = MagicMock(spec=ChatOpsProviderProtocol)
        provider.complete_chat_ops = AsyncMock(
            return_value=LLMChatOpsResponse(
                content="not-json",
                finish_reason=None,
                raw_payload={"choices": []},
            )
        )

        providers = MagicMock()
        providers.primary = provider
        providers.fallback = None
        providers.fallback_is_remote = False

        sessions = MagicMock(spec=ToolSessionRepositoryProtocol)
        sessions.get = AsyncMock(return_value=None)
        sessions.get_or_create = AsyncMock()

        turns = MagicMock(spec=ToolSessionTurnRepositoryProtocol)
        turns.list_tail = AsyncMock(return_value=[])
        turns.cancel_pending_turn = AsyncMock(return_value=None)
        turns.create_turn = AsyncMock()
        turns.update_status = AsyncMock(return_value=None)

        messages = MagicMock(spec=ToolSessionMessageRepositoryProtocol)
        messages.list_by_turn_ids = AsyncMock(return_value=[])
        messages.create_message = AsyncMock()
        messages.update_message_content_if_pending_turn = AsyncMock(return_value=True)

        clock = MagicMock(spec=ClockProtocol)
        clock.now.return_value = datetime(2025, 1, 1, tzinfo=timezone.utc)
        id_generator = MagicMock(spec=IdGeneratorProtocol)
        turn_id = uuid4()
        user_message_id = uuid4()
        assistant_message_id = uuid4()
        session_id = uuid4()
        id_generator.new_uuid.side_effect = [
            turn_id,
            user_message_id,
            assistant_message_id,
            session_id,
        ]

        actor = make_user(role=Role.CONTRIBUTOR)
        tool_id = uuid4()
        session = _make_tool_session(tool_id=tool_id, user_id=actor.id)
        sessions.get_or_create.return_value = session
        turns.create_turn.return_value = _make_turn(
            turn_id=turn_id,
            tool_session_id=session.id,
            correlation_id=correlation_id,
        )

        capture_store = MagicMock(spec=LlmCaptureStoreProtocol)
        capture_store.write_capture = AsyncMock()

        handler = EditOpsHandler(
            settings=settings,
            providers=providers,
            budget_resolver=DummyChatOpsBudgetResolver(settings),
            payload_parser=DefaultEditOpsPayloadParser(),
            guard=DummyChatGuard(),
            failover=DummyFailover(),
            capture_store=capture_store,
            uow=DummyUow(),
            sessions=sessions,
            turns=turns,
            messages=messages,
            clock=clock,
            id_generator=id_generator,
            token_counters=FakeTokenCounterResolver(),
            system_prompt_loader=lambda _: "prompt",
        )

        result = await handler.handle(
            actor=actor,
            command=EditOpsCommand(
                tool_id=tool_id,
                message="Hej",
                active_file="tool.py",
                selection=None,
                cursor=None,
                virtual_files=_virtual_files(),
            ),
        )

        assert result.enabled is True
        assert result.ops == []

        messages.update_message_content_if_pending_turn.assert_awaited_once()
        turns.update_status.assert_awaited_once()

        capture_store.write_capture.assert_awaited_once()
        kwargs = capture_store.write_capture.await_args.kwargs
        assert kwargs["kind"] == "chat_ops_response"
        assert kwargs["capture_id"] == correlation_id
        payload = kwargs["payload"]
        assert payload["outcome"] == "parse_failed"
        assert payload["tool_id"] == str(tool_id)
        assert payload["extracted_content"] == "not-json"from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

PromptCapability = Literal["inline_completion", "chat_stream", "chat_ops"]


CONTRACT_V2_FRAGMENT = "CONTRACT_V2_FRAGMENT"
HELPERS_FRAGMENT = "HELPERS_FRAGMENT"
RUNNER_CONSTRAINTS_FRAGMENT = "RUNNER_CONSTRAINTS_FRAGMENT"


@dataclass(frozen=True, slots=True)
class PromptTemplate:
    template_id: str
    capability: PromptCapability
    template_path: str
    required_placeholders: frozenset[str]


PROMPT_TEMPLATES: dict[str, PromptTemplate] = {
    "inline_completion_v1": PromptTemplate(
        template_id="inline_completion_v1",
        capability="inline_completion",
        template_path="src/skriptoteket/application/editor/system_prompts/inline_completion_v1.txt",
        required_placeholders=frozenset(
            {
                CONTRACT_V2_FRAGMENT,
                RUNNER_CONSTRAINTS_FRAGMENT,
                HELPERS_FRAGMENT,
            }
        ),
    ),
    "editor_chat_v1": PromptTemplate(
        template_id="editor_chat_v1",
        capability="chat_stream",
        template_path="src/skriptoteket/application/editor/system_prompts/editor_chat_v1.txt",
        required_placeholders=frozenset(
            {
                CONTRACT_V2_FRAGMENT,
                RUNNER_CONSTRAINTS_FRAGMENT,
                HELPERS_FRAGMENT,
            }
        ),
    ),
    "editor_chat_ops_v1": PromptTemplate(
        template_id="editor_chat_ops_v1",
        capability="chat_ops",
        template_path="src/skriptoteket/application/editor/system_prompts/editor_chat_ops_v1.txt",
        required_placeholders=frozenset(
            {
                CONTRACT_V2_FRAGMENT,
                RUNNER_CONSTRAINTS_FRAGMENT,
                HELPERS_FRAGMENT,
            }
        ),
    ),
}


def get_prompt_template(*, template_id: str) -> PromptTemplate:
    try:
        return PROMPT_TEMPLATES[template_id]
    except KeyError as exc:
        raise ValueError(f"Unknown prompt template id: {template_id}") from excYou are the AI assistant in the Skriptoteket script editor.

Your task: propose deterministic edits as structured operations.

You will receive a JSON payload as the user's message with:
- message (Swedish instruction)
- active_file (which virtual file is currently active)
- virtual_files (canonical virtual files)
- optional selection: {from,to}
- optional cursor: {pos}

Return ONLY a JSON object matching this schema (no markdown, no prose outside JSON):

{
  "assistant_message": "Kort, tydlig sammanfattning på svenska.",
  "ops": [
    { "op": "insert" | "replace" | "delete",
      "target_file": "tool.py" | "entrypoint.txt" | "settings_schema.json" | "input_schema.json" | "usage_instructions.md",
      "target": { "kind": "cursor" | "selection" | "document" } | { "kind": "anchor", "anchor": { "match": "...", "placement": "before" | "after" } },
      "content": "Nytt innehåll (krävs för insert/replace)"
    },
    { "op": "patch",
      "target_file": "tool.py" | "entrypoint.txt" | "settings_schema.json" | "input_schema.json" | "usage_instructions.md",
      "patch": "diff --git a/<virtualFileId> b/<virtualFileId>\\n--- a/<virtualFileId>\\n+++ b/<virtualFileId>\\n@@ ...\\n"
    }
  ]
}

Rules:
- JSON only. No markdown, no code fences, no comments.
- Use UTF-8. No trailing commas.
- The user's payload may include `selection` and/or `cursor`.
- If BOTH selection and cursor are omitted, treat the position as unknown and prefer patch/anchor.
- Never use target.kind="selection" if selection is omitted.
- Never use target.kind="cursor" if cursor is omitted.

CRUD ops:
- insert: target.kind must be "cursor" or "anchor". content is required.
  - If target.kind="anchor": anchor.placement ("before"|"after") is required.
- replace: target.kind must be "selection" | "document" | "anchor". content is required.
  - If target.kind="anchor": replace the matched anchor text itself.
- delete: target.kind must be "selection" | "document" | "anchor". content must be omitted.
  - If target.kind="anchor": delete the matched anchor text itself.

Patch ops:
- op="patch" applies to ONE virtual file and MUST include:
  - "target_file": one canonical virtual file id
  - "patch": a unified diff string referencing the same canonical id in both headers:
    - --- a/<virtualFileId>
    - +++ b/<virtualFileId>
- Never reference non-canonical filenames outside virtual_files.
- If no edits are needed, return ops: [] and explain why in assistant_message.

{{RUNNER_CONSTRAINTS_FRAGMENT}}

{{CONTRACT_V2_FRAGMENT}}

{{HELPERS_FRAGMENT}}

## Inputs (env vars; plus SKRIPTOTEKET_ACTION for next_actions)

- Files: `SKRIPTOTEKET_INPUT_MANIFEST` (JSON). Use `files[].path`; do NOT read the manifest from disk.
- `files[].path` is an absolute path under `SKRIPTOTEKET_INPUT_DIR` (e.g. `/work/input/<filename>`).
- Form values (initial run only): `SKRIPTOTEKET_INPUTS` (JSON object; no files).
- Action runs (next_actions): read `SKRIPTOTEKET_ACTION` (env JSON with `{action_id, input, state}`).
- Settings: `SKRIPTOTEKET_MEMORY_PATH` (JSON) under `memory["settings"]`.
- The UI payload is outputs/next_actions/state only (no inputs).

## Output & artifacts

- Return a dict with outputs/next_actions/state (see above).
- Write downloadable artifacts under `output_dir`.from __future__ import annotations

from skriptoteket.protocols.llm import ChatMessage
from skriptoteket.protocols.token_counter import TokenCounterProtocol


def _is_virtual_file_context_message(message: ChatMessage) -> bool:
    meta = message.meta
    return isinstance(meta, dict) and meta.get("kind") == "virtual_file_context"


def _budget_prompt_tokens(
    *, context_window_tokens: int, max_output_tokens: int, safety_margin_tokens: int
) -> int:
    budget = context_window_tokens - max_output_tokens - safety_margin_tokens
    return budget if budget > 0 else 0


def _consume_overflow(tokens: int, overflow: int) -> tuple[int, int]:
    if overflow <= 0:
        return tokens, 0
    if tokens <= 0:
        return 0, overflow
    reduction = overflow if overflow < tokens else tokens
    return tokens - reduction, overflow - reduction


def apply_inline_completion_budget(
    *,
    system_prompt: str,
    prefix: str,
    suffix: str,
    context_window_tokens: int,
    max_output_tokens: int,
    safety_margin_tokens: int,
    system_prompt_max_tokens: int,
    prefix_max_tokens: int,
    suffix_max_tokens: int,
    token_counter: TokenCounterProtocol,
) -> tuple[str, str, str]:
    prompt_budget_tokens = _budget_prompt_tokens(
        context_window_tokens=context_window_tokens,
        max_output_tokens=max_output_tokens,
        safety_margin_tokens=safety_margin_tokens,
    )

    target_total_tokens = system_prompt_max_tokens + prefix_max_tokens + suffix_max_tokens
    overflow = target_total_tokens - prompt_budget_tokens
    if overflow > 0:
        prefix_max_tokens, overflow = _consume_overflow(prefix_max_tokens, overflow)
        suffix_max_tokens, overflow = _consume_overflow(suffix_max_tokens, overflow)
        system_prompt_max_tokens, overflow = _consume_overflow(system_prompt_max_tokens, overflow)

    system_prompt = token_counter.truncate_text_head(
        text=system_prompt, max_tokens=system_prompt_max_tokens
    )
    prefix = token_counter.truncate_text_tail(text=prefix, max_tokens=prefix_max_tokens)
    suffix = token_counter.truncate_text_head(text=suffix, max_tokens=suffix_max_tokens)
    return system_prompt, prefix, suffix


def apply_chat_budget(
    *,
    system_prompt: str,
    messages: list[ChatMessage],
    context_window_tokens: int,
    max_output_tokens: int,
    safety_margin_tokens: int,
    system_prompt_max_tokens: int,
    token_counter: TokenCounterProtocol,
) -> tuple[str, list[ChatMessage]]:
    del (
        system_prompt_max_tokens
    )  # enforced at prompt composition time; never truncate the system prompt here

    prompt_budget_tokens = _budget_prompt_tokens(
        context_window_tokens=context_window_tokens,
        max_output_tokens=max_output_tokens,
        safety_margin_tokens=safety_margin_tokens,
    )

    system_prompt_tokens = token_counter.count_system_prompt(content=system_prompt)

    available_message_tokens = prompt_budget_tokens - system_prompt_tokens
    if available_message_tokens <= 0:
        return system_prompt, []

    if not messages:
        return system_prompt, []

    token_costs = [
        token_counter.count_chat_message(role=message.role, content=message.content)
        for message in messages
    ]
    total_tokens = sum(token_costs)

    start = 0
    while start < len(messages) and total_tokens > available_message_tokens:
        total_tokens -= token_costs[start]
        start += 1

    kept = messages[start:]
    while kept and kept[0].role == "assistant" and not _is_virtual_file_context_message(kept[0]):
        kept = kept[1:]
    return system_prompt, kept


def apply_chat_ops_budget(
    *,
    system_prompt: str,
    messages: list[ChatMessage],
    user_payload: str,
    context_window_tokens: int,
    max_output_tokens: int,
    safety_margin_tokens: int,
    system_prompt_max_tokens: int,
    token_counter: TokenCounterProtocol,
) -> tuple[str, list[ChatMessage], bool]:
    del (
        system_prompt_max_tokens
    )  # enforced at prompt composition time; never truncate the system prompt here

    prompt_budget_tokens = _budget_prompt_tokens(
        context_window_tokens=context_window_tokens,
        max_output_tokens=max_output_tokens,
        safety_margin_tokens=safety_margin_tokens,
    )

    system_prompt_tokens = token_counter.count_system_prompt(content=system_prompt)
    user_payload_tokens = token_counter.count_chat_message(role="user", content=user_payload)

    available_message_tokens = prompt_budget_tokens - system_prompt_tokens - user_payload_tokens
    if available_message_tokens <= 0:
        return system_prompt, [], False

    if not messages:
        return system_prompt, [], True

    token_costs = [
        token_counter.count_chat_message(role=message.role, content=message.content)
        for message in messages
    ]
    total_tokens = sum(token_costs)

    start = 0
    while start < len(messages) and total_tokens > available_message_tokens:
        total_tokens -= token_costs[start]
        start += 1

    kept = messages[start:]
    while kept and kept[0].role == "assistant" and not _is_virtual_file_context_message(kept[0]):
        kept = kept[1:]
    return system_prompt, kept, Truefrom __future__ import annotations

import re
from collections.abc import Callable
from dataclasses import dataclass
from typing import Mapping

from skriptoteket.application.editor.ai_prompt import load_system_prompt_text
from skriptoteket.application.editor.prompt_fragments import (
    contract_v2_fragment,
    helpers_fragment,
    runner_constraints_fragment,
)
from skriptoteket.application.editor.prompt_templates import (
    CONTRACT_V2_FRAGMENT,
    HELPERS_FRAGMENT,
    RUNNER_CONSTRAINTS_FRAGMENT,
    PromptCapability,
    PromptTemplate,
    get_prompt_template,
)
from skriptoteket.config import Settings
from skriptoteket.protocols.token_counter import TokenCounterProtocol

_PLACEHOLDER_PATTERN = re.compile(r"\{\{([A-Z0-9_]+)\}\}")


class PromptTemplateError(Exception):
    pass


@dataclass(frozen=True, slots=True)
class ComposedSystemPrompt:
    template_id: str
    capability: PromptCapability
    text: str
    estimated_tokens: int


TemplateTextLoader = Callable[[str], str]


def _find_placeholders(template_text: str) -> set[str]:
    return {match.group(1) for match in _PLACEHOLDER_PATTERN.finditer(template_text)}


def _replace_placeholders(*, template_text: str, fragments: Mapping[str, str]) -> str:
    def replace(match: re.Match[str]) -> str:
        name = match.group(1)
        if name not in fragments:
            raise PromptTemplateError(f"Unknown placeholder: {name}")
        return fragments[name]

    return _PLACEHOLDER_PATTERN.sub(replace, template_text)


def _system_prompt_max_tokens(*, settings: Settings, capability: PromptCapability) -> int:
    if capability == "inline_completion":
        return settings.LLM_COMPLETION_SYSTEM_PROMPT_MAX_TOKENS
    if capability == "chat_stream":
        return settings.LLM_CHAT_SYSTEM_PROMPT_MAX_TOKENS
    if capability == "chat_ops":
        return settings.LLM_CHAT_OPS_SYSTEM_PROMPT_MAX_TOKENS
    raise ValueError(f"Unknown PromptCapability: {capability}")


def build_default_fragments(*, settings: Settings) -> dict[str, str]:
    return {
        CONTRACT_V2_FRAGMENT: contract_v2_fragment(),
        RUNNER_CONSTRAINTS_FRAGMENT: runner_constraints_fragment(settings=settings),
        HELPERS_FRAGMENT: helpers_fragment(),
    }


def compose_system_prompt(
    *, template_id: str, settings: Settings, token_counter: TokenCounterProtocol
) -> ComposedSystemPrompt:
    try:
        template = get_prompt_template(template_id=template_id)
    except ValueError as exc:
        raise PromptTemplateError(str(exc)) from exc

    return compose_system_prompt_from_template(
        template=template,
        settings=settings,
        token_counter=token_counter,
    )


def compose_system_prompt_from_template(
    *,
    template: PromptTemplate,
    settings: Settings,
    template_text_loader: TemplateTextLoader | None = None,
    token_counter: TokenCounterProtocol,
) -> ComposedSystemPrompt:
    def default_loader(prompt_path: str) -> str:
        return load_system_prompt_text(prompt_path=prompt_path)

    loader = template_text_loader or default_loader

    try:
        template_text = loader(template.template_path)
    except OSError as exc:
        raise PromptTemplateError(
            f"Failed to load prompt template '{template.template_id}'."
        ) from exc

    placeholders = _find_placeholders(template_text)

    missing_required = template.required_placeholders - placeholders
    if missing_required:
        raise PromptTemplateError(
            "Prompt template is missing required placeholders: "
            + ", ".join(sorted(missing_required))
        )

    fragments = build_default_fragments(settings=settings)
    unknown = placeholders - fragments.keys()
    if unknown:
        raise PromptTemplateError(
            "Prompt template uses unknown placeholders: " + ", ".join(sorted(unknown))
        )

    composed = _replace_placeholders(template_text=template_text, fragments=fragments)
    unresolved = _find_placeholders(composed)
    if unresolved:
        raise PromptTemplateError(
            "Prompt template composition left unresolved placeholders: "
            + ", ".join(sorted(unresolved))
        )

    system_prompt_max_tokens = _system_prompt_max_tokens(
        settings=settings,
        capability=template.capability,
    )
    estimated_tokens = token_counter.count_system_prompt(content=composed)
    if estimated_tokens > system_prompt_max_tokens:
        raise PromptTemplateError(
            "Composed system prompt exceeds budget "
            f"({estimated_tokens} > {system_prompt_max_tokens})."
        )

    return ComposedSystemPrompt(
        template_id=template.template_id,
        capability=template.capability,
        text=composed,
        estimated_tokens=estimated_tokens,
    )


def validate_prompt_templates(*, settings: Settings, token_counter: TokenCounterProtocol) -> None:
    """Validate that all prompt templates compose cleanly under current settings.

    Intended for unit tests (fail fast) and optional startup diagnostics.
    """

    from skriptoteket.application.editor.prompt_templates import PROMPT_TEMPLATES

    for template_id in PROMPT_TEMPLATES:
        compose_system_prompt(
            template_id=template_id, settings=settings, token_counter=token_counter
        )---
type: adr
id: ADR-0051
title: "Chat-first AI editing (structured CRUD ops + diff preview + apply/
undo)"
status: accepted
owners: "agents"
deciders: ["user-lead"]
created: 2026-01-01
updated: 2026-01-11
links: ["EPIC-08", "ST-08-20", "ST-08-21", "ST-08-22", "ST-08-24", "ST-14-17",
"ST-14-30", "ST-08-28", "ADR-0043"]
---

## Context

Skriptoteket’s editor currently has:

- Static “editor intelligence” (lint, hover, completions).
- AI inline completions (“ghost text”, ST-08-14).
- AI edit suggestions MVP (ST-08-16) that returns raw replacement text for a
  selected range.

This works for experienced script authors, but it is not beginner-friendly:

- Ghost text assumes the author can already start writing code.
- The edit MVP depends on the author selecting the correct region and cannot
  naturally express insert/delete operations.
- The preview is not a diff and does not clearly communicate “what will
  change”.

We want a chat-first authoring experience where a novice can describe intent
in Swedish and iteratively refine a script,
while the platform maintains deterministic, auditable edits.

Constraints:

- Privacy: never log prompts, code, or conversation content; metadata-only
  observability.
- Safety: proposed edits must be previewable (diff), explicitly applied, and
  easy to undo.
- Budgeting: local inference context window constraints apply (existing
  budgeting + template system).
- Architecture: keep protocol-first DI and keep web/api layers thin (handlers
  own business logic).

## Decision

Introduce a chat-first AI assistant in the script editor that proposes
**structured CRUD edit operations** and uses a
safe preview/apply flow.

### 1) UI placement: editor drawer

- Place AI chat in the editor as a drawer/panel that can be opened without
  leaving the editor.
- Store conversation history server-side as the canonical source of truth (not
  client-side only).

### 2) Edit protocol: structured CRUD operations (v1)

The backend returns a validated list of edit operations that support:

- `insert` (at cursor)
- `replace` (selection or whole document)
- `delete` (selection)

Targets are intentionally limited in v1 to keep edits deterministic:

- whole document
- current selection
- cursor insertion

If the model response is invalid, truncated, or over budget, the system must
fail safely (no partial edits).

### 2.1 Virtual files (multi-document context)

To support tool authoring where “code + schemas + instructions” must be edited
together without boundary violations, AI
edit proposals are expressed against a small set of named **virtual files**:

- `tool.py` (the main script)
- `entrypoint.txt`
- `settings_schema.json`
- `input_schema.json`
- `usage_instructions.md`

The UI may render these as separate editors or as a combined “Pro mode” bundle
view, but the AI protocol targets virtual
files explicitly so:

- diffs can be shown per file
- apply/undo can be atomic across all targeted files
- the assistant cannot accidentally mix JSON schema edits into Python (and
  vice versa)

### 2.2 Edit protocol v2: anchor/patch-based targets

To match coding-assistant expectations when no selection/cursor is provided,
we add a second, location-aware targeting mode that relies on anchors rather
than raw cursor offsets.

- Add `patch` operations that carry a unified diff for a single virtual file.
  The diff must reference the same canonical virtual file id in the `a/` and
  `b/` headers, and apply is **strict** (all hunks must match; no fuzzy apply).
- Add `anchor` targets for insert/replace/delete with an explicit anchor payload
  (exact match + placement) so the assistant can say “insert after/before this
  text” without relying on cursor position.
- If no selection/cursor is supplied, the model must prefer patch/anchor ops
  and must not emit cursor-only inserts.

#### 2.2.1 Triggering v2 + request semantics (required)

Because a CodeMirror editor always has an internal cursor, **v2 must be triggered by request semantics**, not by
“whatever the editor happens to have”.

Definitions:

- **Explicit selection/cursor**: a location that the user intentionally targeted in the active virtual file, and that
  the frontend can resolve at the time it sends `POST /api/v1/editor/edit-ops`.
- **Implicit/unknown location**: the user did not explicitly target a location, or the frontend cannot reliably resolve
  selection/cursor for the active file at send time (e.g. editor view unavailable / not focused).

Frontend rules:

- If a selection exists in the active file, include **both**:
  - `selection: { from, to }`
  - `cursor: { pos }` (cursor position MUST be explicitly defined; default to the selection end)
- If there is no selection but there is an explicitly targeted cursor in the active file, include:
  - `cursor: { pos }`
- If the location is implicit/unknown, omit **both** `selection` and `cursor` to intentionally trigger v2.

Backend rules:

- When `selection` and `cursor` are omitted, the system prompt MUST instruct the model to use `patch` and/or `anchor`
  targeting and MUST treat cursor-only ops as invalid (safe-fail).

#### 2.2.2 Patch op (v2)

Patch ops apply against a single virtual file with backend-first unified-diff application (sanitization + bounded fuzz).

Shape (conceptual):

```json
{
  "op": "patch",
  "target_file": "tool.py",
  "patch": "diff --git a/tool.py b/tool.py\n--- a/tool.py\n+++ b/tool.py\n@@ ...\n"
}
```

Rules:

- `target_file` MUST be one of the canonical virtual file ids.
- The patch MUST reference the same canonical id in both headers (`a/<id>` and `b/<id>`).
- Backend MUST sanitize/normalize predictable LLM noise (code fences, indentation, CRLF, invisible chars, missing
  headers) before attempting apply.
- Apply MUST be atomic (“all hunks or nothing”). Multi-file diffs are rejected.
- Apply uses a **bounded fuzz ladder** to reduce regeneration loops:
  - Stage 0: strict apply (fuzz 0)
  - Stage 0b: whitespace-tolerant strict apply (ignore whitespace in context)
  - Stage 1: fuzz 1
  - Stage 2: fuzz 2
- Safety policy:
  - If `max_offset > 50` lines, treat the diff as stale and fail with a regenerate message.
  - If `fuzz>0` OR `max_offset>10`, the UI MUST show a warning and require an extra confirmation before apply.

#### 2.2.3 Anchor target (v2)

Anchor targeting resolves an edit location by exact string match in the base file.

Shape (conceptual):

```json
{
  "op": "insert",
  "target_file": "tool.py",
  "target": {
    "kind": "anchor",
    "anchor": { "match": "def run_tool():\n", "placement": "after" }
  },
  "content": "..."
}
```

Rules:

- `anchor.match` MUST match the base file **exactly once**.
- If `anchor.match` has zero matches: safe-fail with a user-actionable error (“hittade inte ankaret”).
- If `anchor.match` has more than one match: safe-fail with a user-actionable error (“ankaret är otydligt”).

### 3) Guardrails: diff preview + atomic apply + undo

- The UI MUST render a diff preview of “current” vs “proposed” before applying
  any changes.
- The diff preview UI SHOULD be purpose-built for AI proposals (minimal controls), even if it reuses the underlying diff
  engine used elsewhere in the editor.
- Applying a proposal MUST be a single atomic CodeMirror transaction so a
  single undo reverts the change.
- If the underlying editor content changes after the proposal is generated,
  apply MUST be blocked and the user prompted
    to regenerate.
- Preview and apply MUST be version-gated so “what the user saw is what gets applied”:
  - Preview returns `base_hash` + `patch_id` for the exact base + normalized ops/diff.
  - Apply MUST include the same tokens and MUST return `409` on mismatch; the user must re-preview and confirm again.

### 3.1 Multi-turn conversation (server-side)

- Conversation history MUST be persisted server-side as a per-user chat thread
  keyed by `{user_id, tool_id}` (30-day TTL since last activity, and clear on
  user demand).
- The frontend renders the thread and sends only the newest user message to
  chat-first endpoints (no client-managed transcript rules that drift across
  endpoints).
- When calling the provider, the backend enforces prompt budgets
  deterministically (ADR-0052) using a sliding window:
  drop oldest turns first, and **never truncate** the system prompt.
- If the newest user message cannot fit together with the full system prompt
  and reserved output budget, fail with a user-actionable validation error and
  do not mutate the stored thread.

### 4) Observability + evaluation

- Log metadata only (template id, lengths, outcome, provider/model, latency if
  available).
- Never log prompt text, code text, conversation messages, or model outputs.
- Platform-only “full model response capture” is allowed **only** as an explicit debug
  mechanism when enabled by server config (default: OFF). Captures are written to
  artifact storage with TTL cleanup and are retrievable only via server filesystem access.
  When enabled, captures are written automatically on edit-ops generation and preview failures
  for all users (no per-request opt-in).
  (no tool-developer-facing API surface).
- Keep eval-only response metadata behind an admin-gated dev-only mode
  (existing `X-Skriptoteket-Eval` pattern).

## Consequences

### Positive

- Beginner-friendly entry point (“describe what you want”) without requiring
  region selection expertise.
- Deterministic, auditable changes via structured ops + diff preview.
- Lower risk of “AI did something surprising” due to explicit apply and easy
  undo.

### Negative / trade-offs

- Requires new backend schema validation and failure-handling paths for model
  responses.
- Requires a reusable diff viewer component and a stronger preview/apply UX
  than the current edit MVP.
- Patch/anchor apply adds validation complexity and stricter failure cases
  (invalid hunks or ambiguous anchors must safe-fail).
- Limiting targets in v1 reduces capability (no multi-range or semantic
  refactors) but improves safety.

### Follow-ups (out of scope for this ADR)

- Multi-range operations, semantic refactors, or protected/locked regions.
- Shared conversations across users/maintainers.
- Metrics dashboards; only metadata logging is in scope.import type { EditorView } from "@codemirror/view";
import { computed, onScopeDispose, ref, watch, type Ref } from "vue";

import { createCorrelationId } from "../../api/correlation";
import { isApiError } from "../../api/client";
import {
  applyEditOps,
  previewEditOps,
  requestEditOps as requestEditOpsApi,
  type EditorEditOpsOpInput,
  type EditorEditOpsPreviewResponse,
  type EditorEditOpsResponse,
} from "./editOps/editorEditOpsApi";
import { buildDiffItems, uniqueTargetFiles } from "./editOps/editOpsDiff";
import { resolveEditOpsSelection } from "./editOps/editOpsSelection";
import {
  applyVirtualFiles,
  cloneVirtualFiles,
  createAppliedSnapshot,
  virtualFilesFingerprint,
  type AppliedEditOpsSnapshot,
} from "./editOps/editOpsSnapshots";
import {
  buildEditOpsPanelState,
  type EditOpsDiffItem,
  type EditOpsPanelState,
  type EditOpsProposal,
  type EditorEditOpsCursor,
  type EditorEditOpsPreviewErrorDetails,
  type EditorEditOpsSelection,
  type EditorEditOpsOpOutput,
} from "./editOps/editOpsState";
import {
  virtualFileTextFromEditorFields,
  type VirtualFileId,
  type VirtualFileTextMap,
} from "./virtualFiles";

type UseEditorEditOpsOptions = {
  toolId: Readonly<Ref<string>>;
  allowRemoteFallback: Readonly<Ref<boolean>>;
  isReadOnly: Readonly<Ref<boolean>>;
  editorView: Readonly<Ref<EditorView | null>>;
  fields: {
    entrypoint: Ref<string>;
    sourceCode: Ref<string>;
    settingsSchemaText: Ref<string>;
    inputSchemaText: Ref<string>;
    usageInstructions: Ref<string>;
  };
  createBeforeApplyCheckpoint: () => Promise<void> | void;
};

type EditOpsRequestResult = {
  response: EditorEditOpsResponse;
  message: string;
  activeFile: VirtualFileId;
  selection: EditorEditOpsSelection | null;
  cursor: EditorEditOpsCursor | null;
  correlationId: string | null;
};

const DEFAULT_ACTIVE_FILE: VirtualFileId = "tool.py";
const EXPLICIT_CURSOR_TTL_MS = 45_000;

export function useEditorEditOps(options: UseEditorEditOpsOptions) {
  const {
    toolId,
    allowRemoteFallback,
    isReadOnly,
    editorView,
    fields,
    createBeforeApplyCheckpoint,
  } = options;

  const proposal = ref<EditOpsProposal | null>(null);
  const lastApplied = ref<AppliedEditOpsSnapshot | null>(null);
  const isRequesting = ref(false);
  const isPreviewing = ref(false);
  const isApplying = ref(false);
  const requestStartedAt = ref<number | null>(null);
  const requestNow = ref(Date.now());
  let requestInterval: ReturnType<typeof setInterval> | null = null;
  const requestError = ref<string | null>(null);
  const previewError = ref<string | null>(null);
  const previewErrorDetails = ref<EditorEditOpsPreviewErrorDetails | null>(null);
  const applyError = ref<string | null>(null);
  const undoError = ref<string | null>(null);
  const previewResponse = ref<EditorEditOpsPreviewResponse | null>(null);
  const previewBaseFiles = ref<VirtualFileTextMap | null>(null);
  const confirmationAccepted = ref(false);
  const lastExplicitCursorInteractionAt = ref<number | null>(null);
  const aiPosition = ref<"after" | "before">("after");

  const currentFiles = computed(() =>
    virtualFileTextFromEditorFields({
      entrypoint: fields.entrypoint.value,
      sourceCode: fields.sourceCode.value,
      settingsSchemaText: fields.settingsSchemaText.value,
      inputSchemaText: fields.inputSchemaText.value,
      usageInstructions: fields.usageInstructions.value,
    }),
  );

  const currentFingerprint = computed(() => virtualFilesFingerprint(currentFiles.value));

  const requestElapsedSeconds = computed(() => {
    if (!isRequesting.value || requestStartedAt.value === null) return 0;
    return Math.max(0, Math.floor((requestNow.value - requestStartedAt.value) / 1000));
  });

  const isSlowRequest = computed(() => requestElapsedSeconds.value >= 45);

  const targetFiles = computed(() => (proposal.value ? uniqueTargetFiles(proposal.value.ops) : []));

  const diffItems = computed<EditOpsDiffItem[]>(() => {
    if (!proposal.value || !previewResponse.value || !previewBaseFiles.value) return [];
    if (!previewResponse.value.ok) return [];
    const beforeFiles = previewBaseFiles.value;
    const afterFiles = previewResponse.value.after_virtual_files as unknown as VirtualFileTextMap;
    return buildDiffItems({ targetFiles: targetFiles.value, beforeFiles, afterFiles });
  });

  const hasChanges = computed(() => diffItems.value.length > 0);
  const previewMeta = computed(() => previewResponse.value?.meta ?? null);
  const requiresConfirmation = computed(() => previewMeta.value?.requires_confirmation ?? false);

  const applyDisabledReason = computed(() => {
    if (!proposal.value) return null;
    if (isReadOnly.value) return "Editorn är låst för redigering.";
    if (isPreviewing.value) return "Skapar förhandsvisning...";
    if (previewError.value) return previewError.value;
    if (!hasChanges.value) return "Inga ändringar att tillämpa.";
    if (requiresConfirmation.value && !confirmationAccepted.value) {
      return "Bekräfta att du har granskat ändringen.";
    }
    return null;
  });

  const canApply = computed(
    () =>
      Boolean(proposal.value) &&
      !isReadOnly.value &&
      !isPreviewing.value &&
      !previewError.value &&
      hasChanges.value &&
      (!requiresConfirmation.value || confirmationAccepted.value) &&
      !isApplying.value,
  );

  const undoDisabledReason = computed(() => {
    if (!lastApplied.value) return null;
    if (isReadOnly.value) return "Editorn är låst för redigering.";
    if (aiPosition.value !== "after") {
      return "AI-ändringen är redan återställd.";
    }
    if (currentFingerprint.value !== lastApplied.value.afterFingerprint) {
      return "Ändringar har gjorts efter AI-ändringen. Återställ via återställningspunkter.";
    }
    return null;
  });

  const canUndo = computed(
    () =>
      Boolean(lastApplied.value) &&
      !isReadOnly.value &&
      !undoDisabledReason.value &&
      !isApplying.value,
  );

  const redoDisabledReason = computed(() => {
    if (!lastApplied.value) return null;
    if (isReadOnly.value) return "Editorn är låst för redigering.";
    if (aiPosition.value !== "before") {
      return "Ingen AI-ändring att återställa.";
    }
    if (currentFingerprint.value !== lastApplied.value.beforeFingerprint) {
      return "Ändringar har gjorts efter återställning. Återställ via återställningspunkter.";
    }
    return null;
  });

  const canRedo = computed(
    () =>
      Boolean(lastApplied.value) &&
      !isReadOnly.value &&
      !redoDisabledReason.value &&
      !isApplying.value,
  );

  let detachExplicitListeners: (() => void) | null = null;

  function clearErrors(): void {
    requestError.value = null;
    previewError.value = null;
    previewErrorDetails.value = null;
    applyError.value = null;
    undoError.value = null;
  }

  function clearRequestError(): void {
    requestError.value = null;
  }

  function setConfirmationAccepted(nextValue: boolean): void {
    confirmationAccepted.value = nextValue;
  }

  async function loadPreview(params: {
    proposal: EditOpsProposal;
    virtualFiles: VirtualFileTextMap;
  }): Promise<EditorEditOpsPreviewResponse | null> {
    if (!toolId.value) {
      previewError.value = "Ingen editor hittades.";
      return null;
    }

    isPreviewing.value = true;
    previewError.value = null;
    previewErrorDetails.value = null;
    applyError.value = null;

    try {
      const response = await previewEditOps({
        toolId: toolId.value,
        activeFile: params.proposal.activeFile,
        virtualFiles: params.virtualFiles,
        ops: params.proposal.ops as unknown as EditorEditOpsOpInput[],
        selection: params.proposal.selection,
        cursor: params.proposal.cursor,
      });

      previewResponse.value = response;
      previewBaseFiles.value = cloneVirtualFiles(params.virtualFiles);

      const errors = response.errors ?? [];
      const details = response.error_details ?? [];
      previewError.value = response.ok ? null : (errors[0] ?? "Förhandsvisningen misslyckades. Regenerera.");
      previewErrorDetails.value = details[0] ?? null;
      confirmationAccepted.value = false;

      return response;
    } catch (error: unknown) {
      previewResponse.value = null;
      previewBaseFiles.value = null;
      confirmationAccepted.value = false;
      if (isApiError(error)) {
        previewError.value = error.message;
      } else if (error instanceof Error) {
        previewError.value = error.message;
      } else {
        previewError.value = "Det gick inte att förhandsvisa förslaget.";
      }
      return null;
    } finally {
      isPreviewing.value = false;
    }
  }

  async function refreshPreview(): Promise<EditorEditOpsPreviewResponse | null> {
    if (!proposal.value) {
      previewResponse.value = null;
      previewBaseFiles.value = null;
      previewError.value = null;
      previewErrorDetails.value = null;
      confirmationAccepted.value = false;
      return null;
    }

    return await loadPreview({ proposal: proposal.value, virtualFiles: currentFiles.value });
  }

  async function requestEditOps(message: string): Promise<EditOpsRequestResult | null> {
    const trimmed = message.trim();
    if (!trimmed) {
      requestError.value = "Skriv ett meddelande först.";
      return null;
    }
    if (!toolId.value) {
      requestError.value = "Ingen editor hittades.";
      return null;
    }

    clearErrors();
    previewResponse.value = null;
    previewBaseFiles.value = null;
    confirmationAccepted.value = false;
    isRequesting.value = true;

    const hasExplicitCursor =
      lastExplicitCursorInteractionAt.value !== null &&
      Date.now() - lastExplicitCursorInteractionAt.value <= EXPLICIT_CURSOR_TTL_MS;

    const { selection, cursor } = resolveEditOpsSelection({
      view: editorView.value,
      includeCursorWhenNoSelection: hasExplicitCursor,
    });
    const activeFile = DEFAULT_ACTIVE_FILE;
    const virtualFiles = currentFiles.value;

    try {
      const correlationId = createCorrelationId();
      const response = await requestEditOpsApi({
        toolId: toolId.value,
        message: trimmed,
        allowRemoteFallback: allowRemoteFallback.value,
        activeFile,
        virtualFiles,
        selection,
        cursor,
        correlationId,
      });

      if (response.enabled && response.ops.length > 0) {
        const nextProposal: EditOpsProposal = {
          message: trimmed,
          assistantMessage: response.assistant_message,
          ops: response.ops as unknown as EditorEditOpsOpOutput[],
          activeFile,
          selection,
          cursor,
          correlationId,
          createdAt: new Date().toISOString(),
        };
        proposal.value = nextProposal;
        await loadPreview({ proposal: nextProposal, virtualFiles });
      } else {
        proposal.value = null;
        previewResponse.value = null;
        previewBaseFiles.value = null;
        previewError.value = null;
        previewErrorDetails.value = null;
        confirmationAccepted.value = false;
      }

      return { response, message: trimmed, activeFile, selection, cursor, correlationId };
    } catch (error: unknown) {
      proposal.value = null;
      previewResponse.value = null;
      previewBaseFiles.value = null;
      previewErrorDetails.value = null;
      confirmationAccepted.value = false;
      if (isApiError(error)) {
        requestError.value = error.message;
      } else if (error instanceof Error) {
        requestError.value = error.message;
      } else {
        requestError.value = "Det gick inte att skapa ett AI-förslag.";
      }
      return null;
    } finally {
      isRequesting.value = false;
    }
  }

  async function applyProposal(): Promise<boolean> {
    applyError.value = null;
    undoError.value = null;

    if (!proposal.value) return false;
    if (isReadOnly.value) {
      applyError.value = "Editorn är låst för redigering.";
      return false;
    }

    if (!previewResponse.value || previewError.value) {
      await refreshPreview();
    }

    if (!previewResponse.value) {
      applyError.value = previewError.value ?? "Förhandsvisningen saknas. Försök igen.";
      return false;
    }

    if (!previewResponse.value.ok) {
      const errors = previewResponse.value.errors ?? [];
      applyError.value = errors[0] ?? "Förhandsvisningen misslyckades. Regenerera.";
      return false;
    }

    if (!hasChanges.value) {
      applyError.value = "Inga ändringar att tillämpa.";
      return false;
    }

    if (previewResponse.value.meta.requires_confirmation && !confirmationAccepted.value) {
      applyError.value = "Bekräfta att du har granskat ändringen innan du tillämpar.";
      return false;
    }

    const proposalValue = proposal.value;
    const beforeFiles = cloneVirtualFiles(currentFiles.value);

    isApplying.value = true;
    try {
      const response = await applyEditOps({
        toolId: toolId.value,
        activeFile: proposalValue.activeFile,
        virtualFiles: beforeFiles,
        ops: proposalValue.ops as unknown as EditorEditOpsOpInput[],
        baseHash: previewResponse.value.meta.base_hash,
        patchId: previewResponse.value.meta.patch_id,
        selection: proposalValue.selection,
        cursor: proposalValue.cursor,
      });

      if (!response.ok) {
        const errors = response.errors ?? [];
        const errorMessage = errors[0] ?? "Förslaget kunde inte tillämpas. Regenerera.";
        applyError.value = null;
        previewResponse.value = response;
        previewBaseFiles.value = cloneVirtualFiles(beforeFiles);
        previewError.value = errorMessage;
        previewErrorDetails.value = (response.error_details ?? [])[0] ?? null;
        confirmationAccepted.value = false;
        return false;
      }

      await createBeforeApplyCheckpoint();
      const afterFiles = response.after_virtual_files as unknown as VirtualFileTextMap;
      applyVirtualFiles(fields, afterFiles);
      lastApplied.value = createAppliedSnapshot(beforeFiles, afterFiles);
      aiPosition.value = "after";
      proposal.value = null;
      previewResponse.value = null;
      previewBaseFiles.value = null;
      previewError.value = null;
      previewErrorDetails.value = null;
      confirmationAccepted.value = false;
      return true;
    } catch (error: unknown) {
      if (isApiError(error) && error.status === 409) {
        confirmationAccepted.value = false;
        const message = error.message;
        await refreshPreview();
        applyError.value = message;
        return false;
      }

      applyError.value = isApiError(error)
        ? error.message
        : error instanceof Error
            ? error.message
            : "Det gick inte att tillämpa förslaget.";
      return false;
    } finally {
      isApplying.value = false;
    }
  }

  function discardProposal(): void {
    proposal.value = null;
    previewResponse.value = null;
    previewBaseFiles.value = null;
    previewError.value = null;
    previewErrorDetails.value = null;
    applyError.value = null;
    confirmationAccepted.value = false;
  }

  function undoLastApply(): boolean {
    undoError.value = null;
    if (!lastApplied.value) return false;
    if (!canUndo.value) {
      undoError.value = undoDisabledReason.value ?? "Det gick inte att ångra.";
      return false;
    }

    applyVirtualFiles(fields, lastApplied.value.beforeFiles);
    aiPosition.value = "before";
    return true;
  }

  function redoLastApply(): boolean {
    undoError.value = null;
    if (!lastApplied.value) return false;
    if (!canRedo.value) {
      undoError.value = redoDisabledReason.value ?? "Det gick inte att återställa.";
      return false;
    }

    applyVirtualFiles(fields, lastApplied.value.afterFiles);
    aiPosition.value = "after";
    return true;
  }

  watch(
    () => currentFingerprint.value,
    () => {
      if (!lastApplied.value) return;
      if (currentFingerprint.value !== lastApplied.value.afterFingerprint && undoError.value) {
        undoError.value = null;
      }
    },
  );

  onScopeDispose(() => {
    if (detachExplicitListeners) {
      detachExplicitListeners();
      detachExplicitListeners = null;
    }
    if (requestInterval) {
      clearInterval(requestInterval);
      requestInterval = null;
    }
  });

  watch(
    () => isRequesting.value,
    (isActive) => {
      if (requestInterval) {
        clearInterval(requestInterval);
        requestInterval = null;
      }

      if (!isActive) {
        requestStartedAt.value = null;
        requestNow.value = Date.now();
        return;
      }

      requestStartedAt.value = Date.now();
      requestNow.value = Date.now();
      requestInterval = setInterval(() => {
        requestNow.value = Date.now();
      }, 1000);
    },
    { immediate: true },
  );

  watch(
    () => editorView.value,
    (view) => {
      if (detachExplicitListeners) {
        detachExplicitListeners();
        detachExplicitListeners = null;
      }

      if (!view) {
        lastExplicitCursorInteractionAt.value = null;
        return;
      }

      const markExplicit = () => {
        lastExplicitCursorInteractionAt.value = Date.now();
      };

      view.dom.addEventListener("pointerdown", markExplicit);
      view.dom.addEventListener("keydown", markExplicit);

      detachExplicitListeners = () => {
        view.dom.removeEventListener("pointerdown", markExplicit);
        view.dom.removeEventListener("keydown", markExplicit);
      };
    },
    { immediate: true },
  );

  const panelState = computed<EditOpsPanelState>(() =>
    buildEditOpsPanelState({
      proposal: proposal.value,
      diffItems: diffItems.value,
      previewMeta: previewMeta.value,
      previewError: previewError.value,
      previewErrorDetails: previewErrorDetails.value,
      applyError: applyError.value,
      undoError: undoError.value,
      canApply: canApply.value,
      applyDisabledReason: applyDisabledReason.value,
      canUndo: canUndo.value,
      undoDisabledReason: undoDisabledReason.value,
      canRedo: canRedo.value,
      redoDisabledReason: redoDisabledReason.value,
      lastApplied: lastApplied.value,
      aiPosition: aiPosition.value,
      isApplying: isApplying.value,
      requiresConfirmation: requiresConfirmation.value,
      confirmationAccepted: confirmationAccepted.value,
    }),
  );

  return {
    proposal,
    isRequesting,
    requestElapsedSeconds,
    isSlowRequest,
    requestError,
    clearRequestError,
    panelState,
    diffItems,
    previewError,
    previewErrorDetails,
    previewMeta,
    applyError,
    undoError,
    canApply,
    applyDisabledReason,
    canUndo,
    undoDisabledReason,
    isApplying,
    requiresConfirmation,
    confirmationAccepted,
    setConfirmationAccepted,
    requestEditOps,
    applyProposal,
    discardProposal,
    undoLastApply,
    redoLastApply,
    canRedo,
    redoDisabledReason,
  };
}from __future__ import annotations

