class LlmProvider(Provider):
    @provide(scope=Scope.APP)
    def unified_diff_applier(self) -> UnifiedDiffApplierProtocol:
        return SubprocessUnifiedDiffApplier()

    @provide(scope=Scope.APP)
    def llm_capture_store(self, settings: Settings) -> LlmCaptureStoreProtocol:
        return ArtifactsLlmCaptureStore(settings=settings)

    @provide(scope=Scope.APP)
    def token_counter_resolver(self, settings: Settings) -> TokenCounterResolverProtocol:
        return SettingsBasedTokenCounterResolver(settings=settings)

    @provide(scope=Scope.APP)
    def edit_ops_payload_parser(self) -> EditOpsPayloadParserProtocol:
        return DefaultEditOpsPayloadParser()

    @provide(scope=Scope.APP)
    def editor_chat_prompt_builder(self, settings: Settings) -> EditorChatPromptBuilderProtocol:
        return SettingsBasedEditorChatPromptBuilder(settings=settings)

    @provide(scope=Scope.APP)
    async def llm_http_client(self, settings: Settings) -> AsyncIterator[httpx.AsyncClient]:
        timeout = httpx.Timeout(settings.LLM_COMPLETION_TIMEOUT_SECONDS)
        async with httpx.AsyncClient(timeout=timeout) as client:
            yield client

    @provide(scope=Scope.APP)
    def inline_completion_provider(
        self,
        settings: Settings,
        client: httpx.AsyncClient,
    ) -> InlineCompletionProviderProtocol:
        return OpenAIInlineCompletionProvider(settings=settings, client=client)

    @provide(scope=Scope.APP)
    def chat_failover_router(self, settings: Settings) -> ChatFailoverRouterProtocol:
        return InProcessChatFailoverRouter(settings=settings)

    @provide(scope=Scope.APP)
    def chat_ops_budget_resolver(self, settings: Settings) -> ChatOpsBudgetResolverProtocol:
        return SettingsBasedChatOpsBudgetResolver(settings=settings)

    @provide(scope=Scope.APP)
    def chat_stream_providers(
        self,
        settings: Settings,
        client: httpx.AsyncClient,
    ) -> ChatStreamProvidersProtocol:
        primary = OpenAIChatStreamProvider(settings=settings, client=client)

        fallback = None
        fallback_base_url = settings.LLM_CHAT_FALLBACK_BASE_URL.strip()
        fallback_model = settings.LLM_CHAT_FALLBACK_MODEL.strip()
        if fallback_base_url and fallback_model:
            fallback = OpenAIChatStreamProvider(
                settings=settings,
                client=client,
                base_url=fallback_base_url,
                model=fallback_model,
                reasoning_effort=settings.LLM_CHAT_FALLBACK_REASONING_EFFORT,
            )

        return ChatStreamProviders(
            primary=primary,
            fallback=fallback,
            fallback_is_remote=is_remote_llm_endpoint(fallback_base_url) if fallback else False,
        )

    @provide(scope=Scope.APP)
    def chat_ops_providers(
        self,
        settings: Settings,
        client: httpx.AsyncClient,
    ) -> ChatOpsProvidersProtocol:
        primary = OpenAIChatOpsProvider(settings=settings, client=client)

        fallback = None
        fallback_base_url = settings.LLM_CHAT_OPS_FALLBACK_BASE_URL.strip()
        fallback_model = settings.LLM_CHAT_OPS_FALLBACK_MODEL.strip()
        if fallback_base_url and fallback_model:
            fallback = OpenAIChatOpsProvider(
                settings=settings,
                client=client,
                base_url=fallback_base_url,
                model=fallback_model,
                reasoning_effort=settings.LLM_CHAT_OPS_FALLBACK_REASONING_EFFORT,
            )

        return ChatOpsProviders(
            primary=primary,
            fallback=fallback,
            fallback_is_remote=is_remote_llm_endpoint(fallback_base_url) if fallback else False,
        )

    @provide(scope=Scope.APP)
    def chat_inflight_guard(self) -> ChatInFlightGuardProtocol:
        return InProcessChatInFlightGuard()

    @provide(scope=Scope.REQUEST)
    def inline_completion_handler(
        self,
        settings: Settings,
        provider: InlineCompletionProviderProtocol,
        token_counters: TokenCounterResolverProtocol,
    ) -> InlineCompletionHandlerProtocol:
        return InlineCompletionHandler(
            settings=settings,
            provider=provider,
            token_counters=token_counters,
        )

    @provide(scope=Scope.REQUEST)
    def edit_ops_handler(
        self,
        settings: Settings,
        providers: ChatOpsProvidersProtocol,
        budget_resolver: ChatOpsBudgetResolverProtocol,
        payload_parser: EditOpsPayloadParserProtocol,
        guard: ChatInFlightGuardProtocol,
        failover: ChatFailoverRouterProtocol,
        capture_store: LlmCaptureStoreProtocol,
        uow: UnitOfWorkProtocol,
        sessions: ToolSessionRepositoryProtocol,
        turns: ToolSessionTurnRepositoryProtocol,
        messages: ToolSessionMessageRepositoryProtocol,
        clock: ClockProtocol,
        id_generator: IdGeneratorProtocol,
        token_counters: TokenCounterResolverProtocol,
    ) -> EditOpsHandlerProtocol:
        return EditOpsHandler(
            settings=settings,
            providers=providers,
            budget_resolver=budget_resolver,
            payload_parser=payload_parser,
            guard=guard,
            failover=failover,
            capture_store=capture_store,
            uow=uow,
            sessions=sessions,
            turns=turns,
            messages=messages,
            clock=clock,
            id_generator=id_generator,
            token_counters=token_counters,
        )

    @provide(scope=Scope.REQUEST)
    def edit_ops_preview_handler(
        self,
        settings: Settings,
        capture_store: LlmCaptureStoreProtocol,
        patch_applier: UnifiedDiffApplierProtocol,
    ) -> EditOpsPreviewHandlerProtocol:
        return EditOpsPreviewHandler(
            settings=settings,
            capture_store=capture_store,
            patch_applier=patch_applier,
        )

    @provide(scope=Scope.REQUEST)
    def edit_ops_apply_handler(
        self,
        preview: EditOpsPreviewHandlerProtocol,
    ) -> EditOpsApplyHandlerProtocol:
        return EditOpsApplyHandler(preview=preview)

    @provide(scope=Scope.REQUEST)
    def editor_chat_handler(
        self,
        settings: Settings,
        providers: ChatStreamProvidersProtocol,
        guard: ChatInFlightGuardProtocol,
        failover: ChatFailoverRouterProtocol,
        turn_preparer: EditorChatTurnPreparerProtocol,
        stream_orchestrator: EditorChatStreamOrchestratorProtocol,
        token_counters: TokenCounterResolverProtocol,
    ) -> EditorChatHandlerProtocol:
        return EditorChatHandler(
            settings=settings,
            providers=providers,
            guard=guard,
            failover=failover,
            turn_preparer=turn_preparer,
            stream_orchestrator=stream_orchestrator,
            token_counters=token_counters,
        )

    @provide(scope=Scope.REQUEST)
    def editor_chat_turn_preparer(
        self,
        settings: Settings,
        prompt_builder: EditorChatPromptBuilderProtocol,
        uow: UnitOfWorkProtocol,
        sessions: ToolSessionRepositoryProtocol,
        turns: ToolSessionTurnRepositoryProtocol,
        messages: ToolSessionMessageRepositoryProtocol,
        clock: ClockProtocol,
        id_generator: IdGeneratorProtocol,
    ) -> EditorChatTurnPreparerProtocol:
        return EditorChatTurnPreparer(
            settings=settings,
            prompt_builder=prompt_builder,
            uow=uow,
            sessions=sessions,
            turns=turns,
            messages=messages,
            clock=clock,
            id_generator=id_generator,
        )

    @provide(scope=Scope.REQUEST)
    def editor_chat_stream_orchestrator(
        self,
        providers: ChatStreamProvidersProtocol,
        failover: ChatFailoverRouterProtocol,
        uow: UnitOfWorkProtocol,
        turns: ToolSessionTurnRepositoryProtocol,
        messages: ToolSessionMessageRepositoryProtocol,
    ) -> EditorChatStreamOrchestratorProtocol:
        return EditorChatStreamOrchestrator(
            providers=providers,
            failover=failover,
            uow=uow,
            turns=turns,
            messages=messages,
        )

    @provide(scope=Scope.REQUEST)
    def editor_chat_clear_handler(
        self,
        uow: UnitOfWorkProtocol,
        sessions: ToolSessionRepositoryProtocol,
        turns: ToolSessionTurnRepositoryProtocol,
        messages: ToolSessionMessageRepositoryProtocol,
    ) -> EditorChatClearHandlerProtocol:
        return EditorChatClearHandler(uow=uow, sessions=sessions, turns=turns, messages=messages)

    @provide(scope=Scope.REQUEST)
    def editor_chat_history_handler(
        self,
        uow: UnitOfWorkProtocol,
        sessions: ToolSessionRepositoryProtocol,
        turns: ToolSessionTurnRepositoryProtocol,
        messages: ToolSessionMessageRepositoryProtocol,
        clock: ClockProtocol,
    ) -> EditorChatHistoryHandlerProtocol:
        return EditorChatHistoryHandler(
            uow=uow,
            sessions=sessions,
            turns=turns,
            messages=messages,
            clock=clock,
        )from __future__ import annotations

from pathlib import Path
from typing import Literal

from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict

LlmReasoningEffort = Literal["none", "minimal", "low", "medium", "high", "xhigh"]


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    APP_NAME: str = "Skriptoteket"
    APP_VERSION: str = "0.1.0"
    ENVIRONMENT: str = "development"
    SERVICE_NAME: str = "skriptoteket"
    LOG_LEVEL: str = "INFO"
    LOG_FORMAT: Literal["json", "console"] = "json"

    ENABLE_DOCS: bool = True

    # Frontend dev server (legacy SSR + SPA islands; ADR-0025 superseded by ADR-0027)
    # If set, templates render SPA assets from the Vite dev server instead of the production
    # manifest.
    VITE_DEV_SERVER_URL: str | None = None

    DATABASE_URL: str = "postgresql+asyncpg://postgres:postgres@localhost:5432/skriptoteket"
    DATABASE_ECHO: bool = False

    SESSION_COOKIE_NAME: str = "skriptoteket_session"
    SESSION_TTL_SECONDS: int = 60 * 60 * 24 * 7  # 7 days
    DRAFT_LOCK_TTL_SECONDS: int = 60 * 10  # 10 minutes (ADR-0046)

    COOKIE_SECURE: bool = False
    COOKIE_SAMESITE: Literal["lax", "strict", "none"] = "lax"

    # Runner (ST-04-02)
    RUNNER_IMAGE: str = "skriptoteket-runner:latest"
    RUNNER_MAX_CONCURRENCY: int = 1
    RUNNER_TIMEOUT_SANDBOX_SECONDS: int = 60
    RUNNER_TIMEOUT_PRODUCTION_SECONDS: int = 120
    RUNNER_CPU_LIMIT: float = 1.0
    RUNNER_MEMORY_LIMIT: str = "1g"
    RUNNER_PIDS_LIMIT: int = 256
    RUNNER_TMPFS_TMP: str = "rw,noexec,nosuid,nodev,size=256m,mode=1777"

    ARTIFACTS_ROOT: Path = Path("/var/lib/skriptoteket/artifacts")
    ARTIFACTS_RETENTION_DAYS: int = 7

    # Platform-only debug capture (OFF by default; see ADR-0051).
    # Captures are written under ARTIFACTS_ROOT and may contain tool code/model output.
    LLM_CAPTURE_ON_ERROR_ENABLED: bool = False

    LOGIN_EVENTS_RETENTION_DAYS: int = 90

    RUN_OUTPUT_MAX_STDOUT_BYTES: int = 200_000
    RUN_OUTPUT_MAX_STDERR_BYTES: int = 200_000
    RUN_OUTPUT_MAX_HTML_BYTES: int = 500_000
    RUN_OUTPUT_MAX_ERROR_SUMMARY_BYTES: int = 20_000

    UPLOAD_MAX_FILES: int = 20
    UPLOAD_MAX_FILE_BYTES: int = 20_000_000
    UPLOAD_MAX_TOTAL_BYTES: int = 50_000_000

    SESSION_FILES_TTL_SECONDS: int = 60 * 60 * 24  # 24 hours (ADR-0039)
    SANDBOX_SNAPSHOT_TTL_SECONDS: int = 60 * 60 * 24  # 24 hours (ADR-0044)
    SANDBOX_SNAPSHOT_MAX_BYTES: int = 2_000_000  # 2 MB (ADR-0044)

    # Tracing (ST-07-03) - opt-in for monolith
    OTEL_TRACING_ENABLED: bool = False
    OTEL_EXPORTER_OTLP_ENDPOINT: str = "http://localhost:4317"

    # Email (SMTP)
    EMAIL_PROVIDER: Literal["mock", "smtp"] = "mock"
    EMAIL_SMTP_HOST: str = "mail.privateemail.com"
    EMAIL_SMTP_PORT: int = 587
    EMAIL_SMTP_USERNAME: str = ""
    EMAIL_SMTP_PASSWORD: str = ""
    EMAIL_SMTP_USE_TLS: bool = True
    EMAIL_SMTP_TIMEOUT: int = 30
    EMAIL_DEFAULT_FROM_EMAIL: str = "noreply@hule.education"
    EMAIL_DEFAULT_FROM_NAME: str = "Skriptoteket"
    HEALTHZ_SMTP_CHECK_ENABLED: bool = True

    # Email verification
    EMAIL_VERIFICATION_TTL_HOURS: int = 24
    EMAIL_VERIFICATION_BASE_URL: str = "https://skriptoteket.hule.education"

    # LLM API
    LLM_COMPLETION_TEMPLATE_ID: str = "inline_completion_v1"
    LLM_CHAT_TEMPLATE_ID: str = "editor_chat_v1"
    LLM_CHAT_OPS_TEMPLATE_ID: str = "editor_chat_ops_v1"

    LLM_COMPLETION_ENABLED: bool = False
    LLM_COMPLETION_BASE_URL: str = "http://localhost:8082"
    OPENAI_LLM_COMPLETION_API_KEY: str = ""
    LLM_COMPLETION_PROMPT_CACHE_KEY: str = ""
    LLM_COMPLETION_PROMPT_CACHE_RETENTION: Literal["in_memory", "24h"] | None = None
    LLM_COMPLETION_EXTRA_HEADERS: dict[str, str] = Field(default_factory=dict)
    LLM_COMPLETION_MODEL: str = "Devstral-Small-2-24B"
    LLM_COMPLETION_REASONING_EFFORT: LlmReasoningEffort | None = None
    LLM_COMPLETION_MAX_TOKENS: int = 256
    LLM_COMPLETION_TEMPERATURE: float = 0.2
    LLM_COMPLETION_TIMEOUT_SECONDS: int = 30
    LLM_COMPLETION_CONTEXT_WINDOW_TOKENS: int = 4096
    LLM_COMPLETION_CONTEXT_SAFETY_MARGIN_TOKENS: int = 256
    LLM_COMPLETION_SYSTEM_PROMPT_MAX_TOKENS: int = 1024
    LLM_COMPLETION_PREFIX_MAX_TOKENS: int = 2048
    LLM_COMPLETION_SUFFIX_MAX_TOKENS: int = 512

    LLM_CHAT_ENABLED: bool = False
    LLM_CHAT_BASE_URL: str = "http://localhost:8082"
    OPENAI_LLM_CHAT_API_KEY: str = ""
    LLM_CHAT_PROMPT_CACHE_KEY: str = ""
    LLM_CHAT_PROMPT_CACHE_RETENTION: Literal["in_memory", "24h"] | None = None
    LLM_CHAT_EXTRA_HEADERS: dict[str, str] = Field(default_factory=dict)
    LLM_CHAT_MODEL: str = "Devstral-Small-2-24B"
    LLM_CHAT_REASONING_EFFORT: LlmReasoningEffort | None = None
    LLM_CHAT_MAX_TOKENS: int = 2048
    LLM_CHAT_TEMPERATURE: float = 0.2
    LLM_CHAT_TIMEOUT_SECONDS: int = 60
    LLM_CHAT_CONTEXT_WINDOW_TOKENS: int = 16384
    LLM_CHAT_CONTEXT_SAFETY_MARGIN_TOKENS: int = 256
    LLM_CHAT_SYSTEM_PROMPT_MAX_TOKENS: int = 2048
    LLM_CHAT_TAIL_MAX_MESSAGES: int = 60

    # Chat failover (primary -> fallback). Defaults keep failover disabled.
    LLM_CHAT_FALLBACK_BASE_URL: str = ""
    LLM_CHAT_FALLBACK_MODEL: str = ""
    LLM_CHAT_FALLBACK_REASONING_EFFORT: LlmReasoningEffort | None = None

    LLM_CHAT_OPS_ENABLED: bool = False
    LLM_CHAT_OPS_BASE_URL: str = "http://localhost:8082"
    OPENAI_LLM_CHAT_OPS_API_KEY: str = ""
    LLM_CHAT_OPS_PROMPT_CACHE_KEY: str = ""
    LLM_CHAT_OPS_PROMPT_CACHE_RETENTION: Literal["in_memory", "24h"] | None = None
    LLM_CHAT_OPS_EXTRA_HEADERS: dict[str, str] = Field(default_factory=dict)
    LLM_CHAT_OPS_MODEL: str = "Devstral-Small-2-24B"
    LLM_CHAT_OPS_REASONING_EFFORT: LlmReasoningEffort | None = None
    # Output token budgets vary significantly between local llama.cpp and GPT-5 thinking models.
    LLM_CHAT_OPS_MAX_TOKENS: int = 2 * 1024
    LLM_CHAT_OPS_GPT5_MAX_TOKENS: int = 8 * 1024
    LLM_CHAT_OPS_TEMPERATURE: float = 0.2
    LLM_CHAT_OPS_TIMEOUT_SECONDS: int = 120
    LLM_CHAT_OPS_CONTEXT_WINDOW_TOKENS: int = 16 * 1024
    LLM_CHAT_OPS_GPT5_CONTEXT_WINDOW_TOKENS: int = 64 * 1024
    LLM_CHAT_OPS_CONTEXT_SAFETY_MARGIN_TOKENS: int = 256
    # Chat-ops prompts include strict JSON-only schema + rules.
    # They are larger than chat-stream prompts.
    LLM_CHAT_OPS_SYSTEM_PROMPT_MAX_TOKENS: int = 4096

    LLM_CHAT_OPS_FALLBACK_BASE_URL: str = ""
    LLM_CHAT_OPS_FALLBACK_MODEL: str = ""
    LLM_CHAT_OPS_FALLBACK_REASONING_EFFORT: LlmReasoningEffort | None = None

    LLM_CHAT_FAILOVER_STICKY_TTL_SECONDS: int = 60 * 10  # 10 minutes
    LLM_CHAT_FAILOVER_BREAKER_FAILURE_THRESHOLD: int = 2
    LLM_CHAT_FAILOVER_BREAKER_WINDOW_SECONDS: int = 30
    LLM_CHAT_FAILOVER_BREAKER_COOLDOWN_SECONDS: int = 90
    LLM_CHAT_FAILOVER_PRIMARY_MAX_INFLIGHT: int = 0  # 0 = disabled

    # Tokenizers / prompt budgeting (ST-08-27 / ADR-0055)
    # Devstral (Tekken) tokenizer assets are deploy-time mounted; missing assets fall back to
    # heuristic counting.
    LLM_DEVSTRAL_TEKKEN_JSON_PATH: Path | None = None

    # Chat template overhead (tokens). These are intentionally conservative defaults and are added
    # in addition to tokenizing message content.
    LLM_GPT5_MESSAGE_OVERHEAD_TOKENS: int = 3
    LLM_GPT5_SYSTEM_MESSAGE_OVERHEAD_TOKENS: int = 3
    LLM_DEVSTRAL_MESSAGE_OVERHEAD_TOKENS: int = 4
    LLM_DEVSTRAL_SYSTEM_MESSAGE_OVERHEAD_TOKENS: int = 4
    LLM_HEURISTIC_MESSAGE_OVERHEAD_TOKENS: int = 4
    LLM_HEURISTIC_SYSTEM_MESSAGE_OVERHEAD_TOKENS: int = 4from datetime import datetime
from typing import Annotated, Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, JsonValue, model_validator

from skriptoteket.application.scripting.commands import SchemaValidationIssue
from skriptoteket.domain.identity.models import Role
from skriptoteket.domain.scripting.models import RunStatus, VersionState
from skriptoteket.domain.scripting.tool_inputs import ToolInputField
from skriptoteket.domain.scripting.ui.contract_v2 import UiActionField
from skriptoteket.protocols.llm import VirtualFileId
from skriptoteket.web.editor_support import DEFAULT_ENTRYPOINT

EditorSaveMode = Literal["snapshot", "create_draft"]


class EditorToolSummary(BaseModel):
    model_config = ConfigDict(frozen=True)

    id: UUID
    slug: str
    title: str
    summary: str | None
    is_published: bool
    active_version_id: UUID | None


class EditorVersionSummary(BaseModel):
    model_config = ConfigDict(frozen=True)

    id: UUID
    version_number: int
    state: VersionState
    created_at: datetime
    reviewed_at: datetime | None
    published_at: datetime | None


class DraftLockResponse(BaseModel):
    model_config = ConfigDict(frozen=True)

    tool_id: UUID
    draft_head_id: UUID
    locked_by_user_id: UUID
    expires_at: datetime
    is_owner: bool


class EditorBootResponse(BaseModel):
    model_config = ConfigDict(frozen=True)

    tool: EditorToolSummary
    versions: list[EditorVersionSummary]
    selected_version: EditorVersionSummary | None
    draft_head_id: UUID | None
    draft_lock: DraftLockResponse | None
    save_mode: EditorSaveMode
    parent_version_id: UUID | None
    create_draft_from_version_id: UUID | None
    entrypoint: str
    source_code: str
    settings_schema: list[UiActionField] | None = None
    input_schema: list[ToolInputField] = Field(default_factory=list)
    usage_instructions: str | None = None


class EditorEditOpsSelection(BaseModel):
    model_config = ConfigDict(frozen=True, populate_by_name=True)

    start: int = Field(alias="from", ge=0)
    end: int = Field(alias="to", ge=0)

    @model_validator(mode="after")
    def validate_range(self) -> "EditorEditOpsSelection":
        if self.end < self.start:
            raise ValueError("Selection end must be >= start")
        return self


class EditorEditOpsCursor(BaseModel):
    model_config = ConfigDict(frozen=True)

    pos: int = Field(ge=0)


class EditorVirtualFiles(BaseModel):
    model_config = ConfigDict(frozen=True, populate_by_name=True)

    tool_py: str = Field(alias="tool.py")
    entrypoint_txt: str = Field(alias="entrypoint.txt")
    settings_schema_json: str = Field(alias="settings_schema.json")
    input_schema_json: str = Field(alias="input_schema.json")
    usage_instructions_md: str = Field(alias="usage_instructions.md")

    def as_map(self) -> dict[VirtualFileId, str]:
        return {
            "tool.py": self.tool_py,
            "entrypoint.txt": self.entrypoint_txt,
            "settings_schema.json": self.settings_schema_json,
            "input_schema.json": self.input_schema_json,
            "usage_instructions.md": self.usage_instructions_md,
        }


class EditorEditOpsRequest(BaseModel):
    model_config = ConfigDict(frozen=True)

    tool_id: UUID
    message: str = Field(min_length=1)
    allow_remote_fallback: bool = False
    active_file: VirtualFileId
    selection: EditorEditOpsSelection | None = None
    cursor: EditorEditOpsCursor | None = None
    virtual_files: EditorVirtualFiles

    @model_validator(mode="after")
    def validate_active_file(self) -> "EditorEditOpsRequest":
        if self.active_file not in self.virtual_files.as_map():
            raise ValueError("Active file is missing from virtual_files")
        return self


class EditorEditOpsAnchor(BaseModel):
    model_config = ConfigDict(frozen=True)

    match: str = Field(min_length=1)
    placement: Literal["before", "after"] | None = None


class EditorEditOpsCursorTarget(BaseModel):
    model_config = ConfigDict(frozen=True)

    kind: Literal["cursor"]


class EditorEditOpsSelectionTarget(BaseModel):
    model_config = ConfigDict(frozen=True)

    kind: Literal["selection"]


class EditorEditOpsDocumentTarget(BaseModel):
    model_config = ConfigDict(frozen=True)

    kind: Literal["document"]


class EditorEditOpsAnchorTarget(BaseModel):
    model_config = ConfigDict(frozen=True)

    kind: Literal["anchor"]
    anchor: EditorEditOpsAnchor


EditorEditOpsTarget = Annotated[
    EditorEditOpsCursorTarget
    | EditorEditOpsSelectionTarget
    | EditorEditOpsDocumentTarget
    | EditorEditOpsAnchorTarget,
    Field(discriminator="kind"),
]


class EditorEditOpsInsertOp(BaseModel):
    model_config = ConfigDict(frozen=True)

    op: Literal["insert"]
    target_file: VirtualFileId
    target: EditorEditOpsTarget
    content: str = Field(min_length=1)

    @model_validator(mode="after")
    def validate_insert(self) -> "EditorEditOpsInsertOp":
        if self.target.kind not in {"cursor", "anchor"}:
            raise ValueError("Insert ops must target cursor or anchor")
        if self.target.kind == "anchor" and self.target.anchor.placement is None:
            raise ValueError("Anchor placement is required for insert ops")
        return self


class EditorEditOpsReplaceOp(BaseModel):
    model_config = ConfigDict(frozen=True)

    op: Literal["replace"]
    target_file: VirtualFileId
    target: EditorEditOpsTarget
    content: str = Field(min_length=1)

    @model_validator(mode="after")
    def validate_replace(self) -> "EditorEditOpsReplaceOp":
        if self.target.kind == "cursor":
            raise ValueError("Replace ops must target selection, document, or anchor")
        return self


class EditorEditOpsDeleteOp(BaseModel):
    model_config = ConfigDict(frozen=True)

    op: Literal["delete"]
    target_file: VirtualFileId
    target: EditorEditOpsTarget
    content: None = None

    @model_validator(mode="after")
    def validate_delete(self) -> "EditorEditOpsDeleteOp":
        if self.target.kind == "cursor":
            raise ValueError("Delete ops must target selection, document, or anchor")
        return self


class EditorEditOpsPatchOp(BaseModel):
    model_config = ConfigDict(frozen=True)

    op: Literal["patch"]
    target_file: VirtualFileId
    patch: str = Field(min_length=1)


EditorEditOpsOp = Annotated[
    EditorEditOpsInsertOp | EditorEditOpsReplaceOp | EditorEditOpsDeleteOp | EditorEditOpsPatchOp,
    Field(discriminator="op"),
]


class EditorEditOpsResponse(BaseModel):
    model_config = ConfigDict(frozen=True)

    enabled: bool
    assistant_message: str
    ops: list[EditorEditOpsOp]
    base_fingerprints: dict[VirtualFileId, str]


class EditorEditOpsPreviewRequest(BaseModel):
    model_config = ConfigDict(frozen=True)

    tool_id: UUID
    active_file: VirtualFileId
    selection: EditorEditOpsSelection | None = None
    cursor: EditorEditOpsCursor | None = None
    virtual_files: EditorVirtualFiles
    ops: list[EditorEditOpsOp]


class EditorEditOpsPreviewMeta(BaseModel):
    model_config = ConfigDict(frozen=True)

    base_hash: str
    patch_id: str
    requires_confirmation: bool
    fuzz_level_used: int = 0
    max_offset: int = 0
    normalizations_applied: list[str] = Field(default_factory=list)
    applied_cleanly: bool = True


class EditorEditOpsPreviewErrorDetails(BaseModel):
    model_config = ConfigDict(frozen=True)

    op_index: int | None = None
    target_file: VirtualFileId | None = None
    hunk_index: int | None = None
    hunk_header: str | None = None
    expected_snippet: str | None = None
    base_snippet: str | None = None


class EditorEditOpsPreviewResponse(BaseModel):
    model_config = ConfigDict(frozen=True)

    ok: bool
    after_virtual_files: EditorVirtualFiles
    errors: list[str] = Field(default_factory=list)
    error_details: list[EditorEditOpsPreviewErrorDetails] = Field(default_factory=list)
    meta: EditorEditOpsPreviewMeta


class EditorEditOpsApplyRequest(EditorEditOpsPreviewRequest):
    model_config = ConfigDict(frozen=True)

    base_hash: str
    patch_id: str


class EditorChatRequest(BaseModel):
    model_config = ConfigDict(frozen=True)

    message: str = Field(min_length=1)
    base_version_id: UUID | None = None
    allow_remote_fallback: bool = False
    active_file: VirtualFileId | None = None
    virtual_files: EditorVirtualFiles | None = None

    @model_validator(mode="after")
    def validate_virtual_file_context(self) -> "EditorChatRequest":
        if self.active_file is not None and self.virtual_files is None:
            raise ValueError("virtual_files is required when active_file is provided")
        if self.virtual_files is not None and self.active_file is not None:
            if self.active_file not in self.virtual_files.as_map():
                raise ValueError("Active file is missing from virtual_files")
        return self


